@dataclass
class Act:
    "One tool call, from the moment it starts to whatever it returned."
    tool: str
    args: dict = field(default_factory=dict)
    summary: str = ''
    detail: str = ''
    ok: bool = True
    done: bool = False
    secs: float = 0.0
    started: float = field(default_factory=time.time)
    id: str = field(default_factory=lambda: uuid.uuid4().hex[:12])
    turn_id: str = ''
    revision: int = 0
    branch_id: str = 'main'
    parent_action_id: str = ''
    run_id: str = ''          # run whose model made this call
    state: str = 'running'    # 'awaiting' for an approval a person has yet to answer
    kind: str = ''            # 'ask' for an approval, else from the tool
    ask_id: str = ''          # the `Ask` an approval row stands for

    def __post_init__(self): self.kind = self.kind or _kind_of(self.tool)

    @property
    def icon(self): return ICONS.get(self.kind, ICONS['tool'])

    @property
    def in_prompt(self):
        "Whether this row is an approval that is waiting or granted. A frontend with its own approval prompt shows such a row there."
        return self.kind == 'ask' and (not self.done or self.ok)

    def finish(self, out, ok=True):
        self.detail = _clip(out)
        self.ok, self.done, self.state = ok, True, ('complete' if ok else 'failed')
        self.secs = round(time.time() - self.started, 2)
        return self

    def line(self):
        "The one-line text: icon, summary and duration. A running call shows an hourglass instead of the icon."
        if self.state == 'awaiting': return f'🔐 waiting for approval: {self.summary}'
        if not self.done: return f'⏳ {self.summary}'
        tail = f'  ({self.secs:.1f}s)' if self.secs >= 0.5 else ''
        return f'{"" if self.ok else "⚠️ "}{self.icon} {self.summary}{tail}'

    def md(self, fold=True):
        "This call as markdown: the line, with the result folded under it when there is one."
        if not (self.detail and fold): return f'- {self.line()}'
        body = self.detail.replace('```', '`​``')     # a fence in a result must not end ours
        return (f'- {self.line()}\n\n'
                f'  <details><summary>result</summary>\n\n  ```\n{_indent(body)}\n  ```\n\n  </details>')

    def dict(self):
        return {'id': self.id, 'action_id': self.id, 'turn_id': self.turn_id,
                'revision': self.revision, 'branch_id': self.branch_id,
                'parent_action_id': self.parent_action_id, 'run_id': self.run_id, 'state': self.state, 'ask_id': self.ask_id,
                'tool': self.tool, 'kind': self.kind, 'icon': self.icon,
                'summary': self.summary, 'line': self.line(), 'detail': self.detail,
                'ok': self.ok, 'done': self.done, 'secs': self.secs,
                'args': {k: _arg(v) for k, v in (self.args or {}).items()}}


ARG_TEXT = 2000   #: chars kept of each string argument


def _arg(v):
    "One argument as persisted, with every string clipped to `ARG_TEXT`."
    if v is None or isinstance(v, (bool, int, float)): return v
    def deep(x):
        if isinstance(x, str): return x if len(x) <= ARG_TEXT else x[:ARG_TEXT] + '…'
        if isinstance(x, dict): return {str(k): deep(u) for k, u in x.items()}
        if isinstance(x, (list, tuple)): return [deep(u) for u in x]
        return x if x is None or isinstance(x, (bool, int, float)) else str(x)
    return deep(v)


def _clip(out, n=MAX_DETAIL):
    s = '' if out is None else str(out)
    return s if len(s) <= n else s[:n] + f'\n…[{len(s)-n} more chars]'


def _indent(s, pad='  '): return '\n'.join(pad + l for l in s.splitlines())

def _resumed_acts(acts):
    "Persisted tool calls as text, for a context rebuilt from the log rather than a snapshot."
    rows = []
    for a in acts or ():
        if not isinstance(a, dict) or not a.get('tool') or a.get('parent_action_id'): continue
        if a.get('kind') == 'ask' and a.get('ok', True): continue   # the approved call has its own row; a refusal is kept
        args = ', '.join(f'{k}={_1(v, 300) if isinstance(v, str) else v}' for k, v in (a.get('args') or {}).items())
        row = f"- {a['tool']}({args})" + ('' if a.get('ok', True) else '  [failed]')
        if a.get('detail'): row += '\n' + _indent(_clip(a['detail'], RESUME_DETAIL))
        rows.append(row)
    if not rows: return ''
    return ('<earlier_tool_calls note="replayed from a saved session; arguments and results are truncated">\n'
            + '\n'.join(rows) + '\n</earlier_tool_calls>\n\n')

