DENIED = 'Denied by human operator'

DFLT_TIMEOUT = 300      # seconds; None waits forever
MAX_PREVIEW = 2000      # chars

def _tc(tool_call):
    "Canonical `(name, args)` from a tool call."
    fn = tool_call.get('function') or {}
    return tc_name(tool_call), parse_args(fn.get('arguments'))

SECRET_ARGS = {}   #: tool name -> the arguments it marks `secret_args`, whose values are never kept

def _hidden(name, args):
    "`args` as kept and shown: each secret argument's value is `[SECRET]`."
    ks = SECRET_ARGS.get(name, ())
    return {k: '[SECRET]' if k in ks else v for k, v in args.items()} if ks and isinstance(args, dict) else args

# %% ../nbs/03_agent.ipynb #f0c058fe
def _fmt_cmds(commands):
    "exhash commands, a list of lists or its JSON, as one readable block."
    try:
        cmds = json.loads(commands) if isinstance(commands, str) else commands
        if not isinstance(cmds, list): raise ValueError
    except Exception:
        return str(commands)[:MAX_PREVIEW]
    out = []
    for c in cmds:
        if not isinstance(c, (list, tuple)) or not c: out.append(str(c)); continue
        addr, op, rest = c[0], (c[1] if len(c) > 1 else ''), list(c[2:])
        body = '\n'.join('    ' + str(r).replace('\n', '\n    ') for r in rest)
        out.append(f'{addr} {op}' + (f'\n{body}' if body else ''))
    return '\n'.join(out)


def preview_for(name, args, host=None):
    "What this call would do, as text a person can read quickly."
    p = args.get('path', '')
    if path_write(name, args): return (f"saves {', '.join(write_targets(name, args))}\n\n{args.get('prompt', '')}")[:MAX_PREVIEW]
    if name == 'edit_file':   return f'{p}\n\n{_fmt_cmds(args.get("commands", ""))}'[:MAX_PREVIEW]
    if name == 'edit_cell':
        cid = args.get('cell_id', '?')
        try:
            es = edits(args.get('edits', []))
            if not es: return f'{p} cell {cid}\n\nno edits given'
            if host is not None and hasattr(host, 'nb_cell'):
                before = host.nb_cell(p, cid)[2]
                return f'{p} cell {cid}\n\n{diff_text(before, apply_edits(before, es), f"{p}#{cid}")}'[:MAX_PREVIEW]
            return f'{p} cell {cid}\n\n' + '\n'.join(f'- {o}\n+ {n}' for o, n in es)[:MAX_PREVIEW]
        except Exception as e: return f'{p} cell {cid}\n\n{agent_err(e)}'
    if name == 'create_file':
        text, exists = args.get('text', ''), False
        try: exists = bool(host and host.check(p).exists())
        except Exception: pass
        head = f'{p}  ({"OVERWRITES an existing file" if exists else "new file"}, {len(text)} chars)\n\n'
        return (head + text)[:MAX_PREVIEW]
    if name == 'add_cell':
        return f'{p}  (new {args.get("cell_type","code")} cell at {args.get("index",-1)})\n\n{args.get("source","")}'[:MAX_PREVIEW]
    if name == 'run_python':  return str(args.get('code', ''))[:MAX_PREVIEW]
    if name == 'run_shell':   return (f"$ {args.get('command', '')}" + (f'\n  in {c}' if (c := args.get('cwd')) else ''))[:MAX_PREVIEW]
    if name in GIT_WRITE_TOOLS and host is not None:
        try: where = f'in {git_repo(host, p).root}'
        except Exception as e: where = agent_err(e)
        return f'{where}\n\n{json.dumps(args, indent=2, default=str)}'[:MAX_PREVIEW]
    if name == 'replace_text' and host is not None:
        try:
            if not (es := edits(args.get('edits', []))): return f'{p}\n\nno edits given'
            return diff_text(before := host.read(p) or '', apply_edits(before, es), p)[:MAX_PREVIEW]
        except Exception as e: return f'{p}\n\n{agent_err(e)}'
    return json.dumps(args, indent=2, default=str)[:MAX_PREVIEW]


