EDIT_GROUPS = ('file', 'notebook')
ALWAYS_ASK = ('add_root', 'restart_kernel', 'page_eval')   #: `edits` mode does not cover these; `auto` approves them, `off` refuses them
REMOVED_TOOLS = frozenset({'add_todo', 'list_plan', 'delegate_parallel', 'delegate_status', 'remember_note',
                           'watch_folder', 'list_folder_watches', 'cancel_folder_watch', 'check_folders', 'memory_topics', 'poll_watches'})
DOOM_LOOP = 3                      #: identical gated calls in a row that force an ask

def subject(name, args):
    "What a saved rule is matched against: the command, else the path, else the summary."
    return str(args.get('command') or args.get('path') or _summary(name, args))


def call_key(name, args):
    "One call as a hashable: the same tool with the same arguments, however the dict is ordered."
    try: return name, json.dumps(args, sort_keys=True, default=str)
    except Exception: return name, str(args)


def _times(n): return {2: 'twice', 3: 'three times'}.get(n, f'{n} times')


def _load_rules(path):
    "Saved rules as `(tool, pattern, verdict)` triples, and why they could not be read."
    try: return [tuple(r) for r in json.loads(path.read_text())] if path and path.exists() else [], ''
    except Exception as e: return [], f'{path.name}: {agent_err(e)}'

APPROVE_MODES = ('off', 'ask', 'edits', 'auto')   #: strictest first

VERDICTS = ('allow', 'deny', 'ask')   #: what an approval `policy` may return; anything else falls through
NO_LISTENER = ('refuse', 'wait')   #: an ask with nobody listening is refused at once, or waits for a listener
ON_TIMEOUT = ('refuse', 'allow')   #: what an ask nobody answers in time becomes
PERSON_ONLY = frozenset({'peer ask'})   #: requests only a person answers: no mode, saved rule, policy, timeout or cancelled turn decides them

class Approvals:
    "The approval gate: it holds each request waiting for an answer and wakes the model's thread when a person answers."

    def __init__(self,
                 tools=(),                  # tool names that need approval
                 mode='ask',                # 'ask', 'edits', 'auto' or 'off'
                 timeout=DFLT_TIMEOUT,      # seconds to wait; None waits forever
                 host=None,                 # for previews that read disk
                 on_ask=None,               # called with the `Ask` when one is raised
                 on_answer=None,            # called with the `Ask` when it is answered
                 rules_path=None,           # saved allow/deny rules, `<cfg>/approvals.json`
                 no_listener='refuse',      # with nobody listening: 'refuse', or 'wait' for a listener
                 on_timeout='refuse',       # an ask nobody answers in time: 'refuse' or 'allow'
                 policy=None):              # `fn(name, args)` -> a `VERDICTS` entry or None, consulted before rules and modes
        if no_listener not in NO_LISTENER: raise ValueError(f'no_listener must be one of {NO_LISTENER}')
        if on_timeout not in ON_TIMEOUT: raise ValueError(f'on_timeout must be one of {ON_TIMEOUT}')
        self.tools, self.mode, self.timeout, self.host = frozenset(tools), mode, timeout, host
        self.no_listener, self.on_timeout, self.policy = no_listener, on_timeout, policy
        self.rules_path = Path(rules_path) if rules_path else None
        self.rules, self.problem = _load_rules(self.rules_path)
        self.on_ask, self.on_answer = on_ask, on_answer
        self.current = None       # the newest ask, for a frontend that shows one at a time
        self._asks = {}           # id -> every ask still waiting, oldest first
        self.closed = False
        self.history = []
        self._watchers = []
        self._lock = threading.Lock()
        self._repeat, self._streak = None, 0


    @property
    def listeners(self): return len(self._watchers)

    def rule_for(self, name, args):
        "'allow' or 'deny' from the first saved rule matching this call, else None."
        s = subject(name, args)
        return next((v for t, pat, v in self.rules if t == name and fnmatch.fnmatch(s, pat)), None)

    def prune(self):
        "Drop saved rules for `REMOVED_TOOLS`, noting each on `problem`."
        gone = [r for r in self.rules if r[0] in REMOVED_TOOLS]
        if not gone: return gone
        self.rules = [r for r in self.rules if r[0] not in REMOVED_TOOLS]
        notes = [f'dropped saved rule for {t} (no such tool)' for t in dict.fromkeys(r[0] for r in gone)]
        self.problem = '\n'.join(x for x in [self.problem, *notes] if x)
        self._save()
        return gone

    def _save(self):
        if self.rules_path is None: return
        self.rules_path.parent.mkdir(parents=True, exist_ok=True)
        with atomic_save(self.rules_path, 'w') as f: json.dump(self.rules, f, indent=1)

    def always(self, name, pattern, verdict='allow', glob=False):
        "Save a rule that allows or denies `name` calls matching `pattern` without asking."
        pattern = pattern if glob else glob_escape(pattern)
        self.rules.append((name, pattern, verdict))
        self._save()
        return f'always {verdict}: {name} {pattern}'

    def listen(self, on_ask=None, on_answer=None):
        "Register the `on_ask` and `on_answer` callbacks of a frontend. The frontend receives every ask already waiting. Returns a function that unregisters it."
        w = (on_ask, on_answer)
        with self._lock:
            self._watchers.append(w)
            waiting = [a for a in self._asks.values() if a.pending]
        for a in waiting: self._show(w, a)
        done = [False]
        def stop():
            if done[0]: return
            done[0] = True
            with self._lock:
                if w in self._watchers: self._watchers.remove(w)
        return stop

    def _notify(self, which, a):
        "Call the recorder and every watcher. Exceptions from the callbacks are discarded. A watcher receives each ask once."
        if (f := getattr(self, f'on_{which}')):
            try: f(a)
            except Exception: pass
        for w in list(self._watchers):
            if which == 'ask': self._show(w, a)
            elif w[1]:
                try: w[1](a)
                except Exception: pass

    def _show(self, w, a):
        "Call watcher `w` with ask `a` once, even when `listen` and the raising of the ask run at the same time."
        with self._lock:
            if not (w[0] and a.pending) or id(w) in a._shown: return
            a._shown.add(id(w))
        try: w[0](a)
        except Exception: pass

    @property
    def waiting(self):
        "Every request waiting for an answer, oldest first."
        with self._lock: return [a for a in self._asks.values() if a.pending]

    @property
    def pending(self):
        "The oldest request waiting for an answer, or None."
        return next(iter(self.waiting), None)

    def answer(self, id, ok, note='', session=False, scope='auto'):
        "Answer the waiting request `id`. A second answer to the same request returns None. An approval with `session` true sets the mode to `scope`."
        with self._lock:   # `close` and a timeout take this lock. An ask resolves once.
            a = self._asks.pop(id, None)
            if a is None or not a.pending: return None
            if ok and session: self.mode = scope
            a.answer, a.note = bool(ok), note or ''
            if ok and session and not a.note:
                a.note = 'approved for the rest of this session' if scope == 'auto' else f'writes approved for the rest of this session ({scope})'
        # notify before waking the model thread
        self._notify('answer', a)
        a._done.set()
        return a

    def close(self):
        "Refuse everything still waiting, and every ask after it."
        with self._lock:
            if self.closed: return []
            self.closed = True
            waiting = [a for a in self.history if a.pending]
            for a in waiting: a.answer, a.note = False, 'the session closed before this was answered'
            self._asks.clear()
        for a in waiting:
            a._done.set()
            self._notify('answer', a)
        return waiting

    def _decided(self, a, ok, note):
        "Resolve without a person and call the recorder."
        a.resolve(ok, note)
        self._notify('answer', a)
        return a

    def cancel_all(self, note='the turn was cancelled', run=None):
        "Refuse the waiting asks. Without `run`, refuse all of them. With `run`, refuse the asks that belong to `run`, to a run that `run` started, or to no known run."
        for a in self.waiting:
            # an ask raised off the run's thread names no run and may be this one's, unless only a person answers it
            if run is None or (a.run is None and a.forced != 'person') or _of_run(a.run, run): self.answer(a.id, False, note)


    def gate(self, tool_call):
        "The `approve(tool_call)` function both backends call. It blocks the model's thread until the ask is answered."
        return self.request(*_tc(tool_call))

    def ask(self, name, args):
        "Add an undecided `Ask` for this call to `history` and return it."
        run, args = current_run(), _hidden(name, args)
        a = Ask(tool=name, args=args, summary=_summary(name, args), preview=preview_for(name, args, self.host),
                run_id=getattr(run, 'id', '') or '', run=run)
        self.history.append(a)
        return a

    @staticmethod
    def edits_cover(name):
        "Whether `edits` mode runs `name` unasked: a file or notebook write, never `ALWAYS_ASK`."
        return group_of(name) in EDIT_GROUPS and name not in ALWAYS_ASK

    def _verdict(self, name, args):
        "The verdict of `policy` for this call. A policy that raises returns 'ask'. A failing policy never allows."
        if self.policy is None: return None
        try: v = self.policy(name, args)
        except Exception: return 'ask'
        return v if v in VERDICTS else None

    def decide(self, name, args, force=False, ask=None, loop=False):
        "Resolve the `Ask` without a person when the policy, a rule or the mode decides it, else None."
        a = self.ask(name, args) if ask is None else ask
        if name in PERSON_ONLY:
            a.forced = 'person'
            return None
        v = self._verdict(name, args)
        if v == 'deny': return self._decided(a, False, 'denied by the host policy')
        if v == 'ask':
            a.forced = 'policy'
            return None
        if v == 'allow' and not loop: return a.resolve(True)
        if not force and name not in self.tools and not path_write(name, args): return a.resolve(True)
        if self.mode == 'off': return self._decided(a, False, 'approval is switched off for this session')
        if (v := self.rule_for(name, args)) == 'deny': return self._decided(a, False, 'denied by a saved rule')
        if loop: return None
        if v == 'allow': return a.resolve(True, 'allowed by a saved rule')
        if self.mode == 'auto' or (self.mode == 'edits' and self.edits_cover(name)): return a.resolve(True)
        return None

    def _looping(self, name, args):
        "Whether this gated call is the `DOOM_LOOP`th identical one in a row."
        key = call_key(name, args)
        with self._lock:
            self._streak, self._repeat = (self._streak + 1 if key == self._repeat else 1), key
            return self._streak >= DOOM_LOOP

    def set_mode(self, mode):
        "Switch mode. Waiting asks that the new mode decides are answered. Returns a status note."
        if mode not in APPROVE_MODES: return f"usage: /approve [{'|'.join(APPROVE_MODES)}]"
        was, self.mode = self.mode, mode
        return f'approvals: {mode}' if was == mode else f'approvals: {was} -> {mode}{self._settle()}'

    def _settle(self):
        "Answer what is waiting that the new mode decides without a person."
        settled = [a for a in self.waiting if a.forced not in ('policy', 'person') and self.mode != 'ask' and not (self.mode == 'edits' and not self.edits_cover(a.tool))]
        if not settled: return ''
        ok = self.mode != 'off'
        for a in settled: self.answer(a.id, ok, f'answered by /approve {self.mode}')
        return f' · {"approved" if ok else "refused"} what was waiting'

    def request(self, name, args, force=False, timeout=None):
        "Raise one request and wait for the answer. The reason for a refusal is in `reply()` of the resolved `Ask`."
        a = self.ask(name, args)
        loop = (force or name in self.tools or path_write(name, args)) and self._looping(name, args)
        if loop: a.preview, a.forced = f'the same call {_times(self._streak)} running -- allow it?\n\n{a.preview}'.strip(), 'loop'
        if (d := self.decide(name, args, force, ask=a, loop=loop)) is not None: return d
        # under the close lock, or an ask in the gap waits out its timeout
        with self._lock:
            closing, heard = self.closed, bool(self._watchers) or self.no_listener == 'wait'
            if not closing and heard: self._asks[a.id], self.current = a, a
        if closing: return self._decided(a, False, 'the session is closing')
        if not heard:
            why = f'the same call {_times(self._streak)} running, and nothing is listening to ask about it' if loop else 'nothing is listening for approvals, so this could not be asked'
            return self._decided(a, False, why)
        self._notify('ask', a)
        wait_for = self.timeout if timeout is None else timeout
        if not a.wait(wait_for):
            with self._lock:
                late = self._asks.pop(a.id, None) is not None and a.pending
                if late:   # a timeout never allows what the policy or the loop guard put to a person
                    ok = self.on_timeout == 'allow' and not a.forced
                    a.answer, a.note = ok, f"no answer after {wait_for}s; {'allowed' if ok else 'refused'} as the host chose"
            if late:
                a._done.set()
                self._notify('answer', a)
        return a

def _of_run(run, ancestor):
    "Whether `run` is `ancestor` or one of the runs it started."
    while run is not None:
        if run is ancestor: return True
        run = getattr(run, 'parent', None)
    return False

