def skill_catalogue(skills):
    "The briefing's skill list. One line per skill: its name and the first sentence of its description, clipped to `CATALOGUE_CHARS`."
    if not skills: return ''
    def first(desc):
        s = re.split(r'(?<=[.!?])\s', ' '.join((desc or '').split()), maxsplit=1)[0]
        return s if len(s) <= CATALOGUE_CHARS else s[:CATALOGUE_CHARS].rsplit(' ', 1)[0].rstrip(',;:') + '…'
    names = {s.name for s in skills}
    point = ''.join(t for n, t in SKILL_POINTERS.items() if n in names)
    rows = '\n'.join(f'- `{s.name}`: {first(s.description)}' for s in skills)
    return f'\n\n## Skills\n\nRead a skill with `read_skill(name)` before the work it covers.{point}\n\n{rows}'

def _inline_text(s, learned, mx=MAX_CONTEXT_FILE):
    "An inlined skill's text. A skill from the `learned` folder is clipped to `mx`."
    t = s.text()
    if learned is None or len(t) <= mx or Path(learned).resolve() not in Path(str(s.where or '')).resolve().parents: return t
    return t[:mx] + f'\n…[truncated; read_skill("{s.name}") for the rest]'

def system_prompt(host, skills=(), inline=INLINE_SKILLS, extra='', tools=(), cfg=None,
                  pictures=True,    # whether the turn model sees a picture a tool returns
                  learned=None):    # the folder `learned_context` reads; None leaves it out

    "The agent's briefing: its identity, folders, rules, skills, lessons and project instructions, then `extra`."
    names = {getattr(t, '__name__', '') for t in tools or ()}
    roots = _folders(host)
    if getattr(host, 'read_outside', False):
        roots += ('\n  Reads may name any path on this machine. Writing, running commands and\n'
                  '  listing files stay inside the folders above.')
    conc = ('\n  Your kernel runs each inspection in its own subshell. This works while one '
            "of the user's cells is still running." if getattr(host, 'concurrent', False) else '')
    live = ('' if 'inspect_python' not in names and names else
            '\n- To *look at* live state, prefer `inspect_python`: neither of its scopes can change\n'
            '  what the user made, so it needs no approval. Start with the default sandbox and pass\n'
            f"  `scope='overlay'` when it refuses a library call you need.{conc}")
    machine = _machine(host, getattr(host, 'environment', lambda: '')())
    sp = f"""You are Ramabana, a coding agent. Follow the user's latest explicit request and the project instructions below. You are working in these folders:
{roots}{machine}

You can search the code index (this repo *and* every installed package), read and edit
files, run commands in the project, run Python in the user's live kernel namespace, read
the web, and read skills that describe the tools already installed here.

How to work:
{work_rules(names, pictures=pictures)}{live}"""
    idx = skill_catalogue(skills)
    if idx: sp += idx
    for name in inline or ():
        if (s := find(skills, name)): sp += f'\n\n## {s.name}\n\n{_inline_text(s, learned)}'
    sp += learned_context(learned) + project_context(host, cfg=cfg)
    return sp + (f'\n\n{extra}' if extra else '')


SMALL_CONTEXT_FILE = 2000   # chars
MASKED_NOTE = ('API keys and tokens in tool output come back as `[SECRET]`, and commands that print the environment are refused; '
               'to check a variable, ask whether it is set: `test -n "$NAME" && echo set`.')

def _machine(host, env):
    "The briefing's `On this machine` block: the host's environment line, and that secrets are masked when its read guard masks them."
    lines = [l for l in (env, MASKED_NOTE if getattr(getattr(host, 'read_guard', None), 'masks_secrets', False) else '') if l]
    return '\n\nOn this machine:\n' + '\n'.join(lines) if lines else ''

def _folders(host):
    "The open folders as the briefing lists them, followed by the folders open for reading only."
    roots = '\n'.join(f'  {r}' for r in host.roots) or '  (no folder open)'
    if (ro := list(getattr(host, 'read_roots', ()) or ())):
        roots += '\n  Open for reading only: search and read them, never write or run commands in them:\n' + '\n'.join(f'    {r}' for r in ro)
    return roots

def small_system_prompt(host, tools=(), cfg=None, learned=None):
    "The small profile's briefing: the folders, one machine line, `SMALL_RULES`, and clipped lessons and project instructions."
    names = {getattr(t, '__name__', '') for t in tools or ()}
    roots = _folders(host)
    env = (getattr(host, 'environment', lambda: '')() or '').strip()
    line = env.splitlines()[0].split('; inspect_python')[0] if env else ''   # `inspect_python` is not offered here
    machine = _machine(host, line)
    return (f"You are Ramabana, a coding agent. Follow the user's latest explicit request. You are working in these folders:\n"
            f"{roots}{machine}\n\nHow to work:\n{work_rules(names, SMALL_RULES)}" + learned_context(learned, SMALL_CONTEXT_FILE, SMALL_CONTEXT_FILE)
            + project_context(host, mx=SMALL_CONTEXT_FILE, cfg=cfg))


