TODO_STATUSES = ('pending', 'active', 'done', 'cancelled')
TODO_MARK = {'pending': '[ ]', 'active': '[▸]', 'done': '[x]', 'cancelled': '[-]'}

@dataclass
class Todo:
    "One step on a session plan."
    id: str
    text: str
    status: str = 'pending'
    note: str = ''
    owner: str = ''           # sub-agent label; '' for the main agent

    def __post_init__(self):
        if self.status not in TODO_STATUSES:
            raise ValueError(f'status must be one of {TODO_STATUSES}')

    def dict(self):
        return dict(id=self.id, text=self.text, status=self.status, note=self.note, owner=self.owner)

    @classmethod
    def from_dict(cls, d):
        if isinstance(d, Todo): return d
        if not isinstance(d, dict): return cls(id=uuid.uuid4().hex[:8], text=str(d))
        return cls(id=str(d.get('id') or uuid.uuid4().hex[:8]),
                   text=str(d.get('text') or ''),
                   status=str(d.get('status') or 'pending'),
                   note=str(d.get('note') or ''),
                   owner=str(d.get('owner') or ''))


class Plan:
    "The session's checklist of steps, with a status for each step."
    def __init__(self, title='', todos=None, updated=0.):
        self.title = str(title or '')
        self.todos, self.updated = [], float(updated or time.time())
        for it in todos or ():
            if isinstance(it, Todo): self.todos.append(it)
            elif isinstance(it, dict): self.todos.append(Todo.from_dict(it))
            else:
                text = str(it).strip()
                if text: self.todos.append(Todo(id=uuid.uuid4().hex[:8], text=text))

    def __bool__(self): return bool(self.title) or bool(self.todos)
    def __len__(self): return len(self.todos)

    def dict(self):
        return dict(title=self.title, updated=self.updated, todos=[t.dict() for t in self.todos])

    @classmethod
    def from_dict(cls, d):
        d = dict(d or {})
        return cls(title=d.get('title') or '', todos=d.get('todos') or [], updated=d.get('updated') or 0.)

    def progress(self):
        "`(done, total)`. Cancelled todos are not counted."
        alive = [t for t in self.todos if t.status != 'cancelled']
        return sum(t.status == 'done' for t in alive), len(alive)

    def active(self):
        return next((t for t in self.todos if t.status == 'active'), None)

    def pending(self):
        return [t for t in self.todos if t.status == 'pending']

    def find(self, key):
        "Find a todo by exact id, unique id prefix or unique text substring. Returns None when no todo or more than one todo matches."
        key = str(key or '').strip()
        if not key: return None
        for t in self.todos:
            if t.id == key: return t
        pref = [t for t in self.todos if t.id.startswith(key)]
        if len(pref) == 1: return pref[0]
        text = [t for t in self.todos if key.lower() in t.text.lower()]
        return text[0] if len(text) == 1 else None

    def _touch(self): self.updated = time.time(); return self

    def clear(self):
        self.title, self.todos = '', []
        return self._touch()

    def set(self, title, items=()):
        "Replace the plan. `items` are todo texts (str), dicts or `Todo` objects."
        self.title = str(title or '').strip()
        out = []
        for it in items or ():
            if isinstance(it, Todo): out.append(it)
            elif isinstance(it, dict): out.append(Todo.from_dict(it))
            else:
                text = str(it).strip()
                if text: out.append(Todo(id=uuid.uuid4().hex[:8], text=text))
        self.todos = out
        return self._touch()

    def add(self, text, status='pending', owner='', id=None):
        t = Todo(id=id or uuid.uuid4().hex[:8], text=str(text).strip(), status=status, owner=owner)
        if not t.text: raise ValueError('todo text is empty')
        self.todos.append(t)
        return self._touch() and t

    def update(self, key, status=None, note=None, text=None, owner=None):
        t = self.find(key)
        if t is None: raise KeyError(f'no todo matches {key!r}')
        if status is not None:
            if status not in TODO_STATUSES: raise ValueError(f'status must be one of {TODO_STATUSES}')
            if status == 'active':
                for o in self.todos:
                    if o is not t and o.status == 'active': o.status = 'pending'
            t.status = status
        if note is not None: t.note = str(note)
        if text is not None: t.text = str(text).strip() or t.text
        if owner is not None: t.owner = str(owner)
        self._touch()
        return t

    def md(self):
        "The checklist as markdown, for a briefing, a status block or a `/plan` reply."
        if not self: return '(no plan)'
        done, total = self.progress()
        head = self.title or 'Plan'
        lines = [f'**{head}**  ·  {done}/{total} done']
        for t in self.todos:
            mark = TODO_MARK.get(t.status, '[ ]')
            own = f'  @{t.owner}' if t.owner else ''
            note = f'  -- {t.note}' if t.note else ''
            lines.append(f'{mark} `{t.id}` {t.text}{own}{note}')
        return '\n'.join(lines)

    def line(self):
        "A status-bar fragment, or '' when the plan is empty."
        if not self: return ''
        done, total = self.progress()
        cur = self.active()
        bit = f'{done}/{total}'
        if cur: bit += f' ▸ {cur.text[:40]}'
        elif self.pending(): bit += f' · next: {self.pending()[0].text[:36]}'
        return bit


def plan_tools(get_plan, save=None):
    "Model-facing `set_plan` and `update_todo` tools over the agent's `Plan`."
    def _save():
        if save:
            try: save()
            except Exception: pass

    @summary(lambda a: f'Set plan: {len(a.get("items") or [])} steps')
    def set_plan(items: list[str], # the steps in order, one text each; an empty list clears the plan
                 ) -> str:
        "Replace the session plan with these step texts; an empty list clears it. Returns the checklist."
        todos = [str(x).strip() for x in (items if isinstance(items, (list, tuple)) else parse_plan_items(items)) if str(x).strip()]
        if not todos: get_plan().clear(); _save(); return 'plan cleared'
        get_plan().set(get_plan().title, todos); _save()
        return get_plan().md()

    @summary(lambda a: f'Todo {a.get("id") or "new"} → {a.get("status") or ("update" if a.get("id") else "add")}')
    def update_todo(id: str = '',     # the todo's id or a unique prefix of it; empty adds `text` as a new step
                    status: str = '', # pending, active, done or cancelled
                    text: str = '',   # the step's new text, or the text of the step to add
                    ) -> str:
        "Change a todo by id or unique prefix (status: pending, active, done, cancelled), or append `text` as a new step when `id` is empty."
        p = get_plan()
        if not id:
            if not text: return err('give `text` to add a step, or `id` to change one')
            try: t = p.add(text, status=status or 'pending')
            except Exception as e: return err('could not add todo', e)
            _save()
            return f'added `{t.id}` ({t.status}): {t.text}\n\n{p.md()}'
        kw = {k: v for k, v in (('status', status), ('text', text)) if v}
        if not kw: return err('nothing to update; pass status or text')
        try: t = p.update(id, **kw)
        except Exception as e: return err('could not update todo', e)
        _save()
        return f'`{t.id}` → {t.status}: {t.text}' + (f' -- {t.note}' if t.note else '') + f'\n\n{p.md()}'

    return [set_plan, update_todo]

PLAN_TOOLS = frozenset(f.__name__ for f in plan_tools(list))
ROOT_ONLY = NO_SUB | PLAN_TOOLS   #: the root turn's own tools; a sub-agent never receives them

