_TOOL_MIN, _TOOL_MAX = 20, 400
_STEP_MIN, _STEP_MAX = 8, 80
SUB_DEPTH_MAX = 2   #: most levels of sub-agents that may delegate again
TREE_SPENT = ('Tool-call budget for delegated work is exhausted. Stop calling tools and '
              'answer with the evidence you have.')

def _sub_steps(n): return 'auto' if str(n).strip().lower() == 'auto' else max(1, min(SUB_STEP_CEILING, int(n)))
def _sub_timeout(s): return max(0., float(s or 0))
def _sub_depth(n): return max(0, min(SUB_DEPTH_MAX, int(n)))

class Agent:
    "One model conversation on a host, with its tools, approvals, activity feed, plan and history."

    def __init__(self,
                 host,
                 model=None,                # turn model; None takes the routing default
                 routing=None,
                 sp=None,                   # override the whole briefing
                 extra_sp='',               # text added after the briefing, which stays
                 global_skills=True,        # read skills from `~/.agents/skills` too
                 approvals=None,            # an `Approvals`; None gates nothing
                 cfg=None,                  # config dir, for skills and extensions
                 compact=None,              # compact automatically at the threshold; None reads config.toml's `compaction.auto`, else True
                 compact_strategy=None,     # 'summary' or deterministic 'surgical'; None reads `compaction.strategy`, else 'summary'
                 kernel_alive=True,         # what the post-compaction note may promise
                 extensions=True,
                 project_extensions=False,  # project extensions run code from the repo; True opts in
                 ext_paths=(),
                 inline_skills=INLINE_SKILLS,
                 subagents=True,
                 subagent_writes=True,     # sub-agents get write tools, behind the same approvals
                 subagent_steps='auto',    # 'auto' lets a delegation ask for up to `SUB_STEP_CEILING` steps; a number caps every delegation's `max_steps`
                 subagent_timeout=SUB_TIMEOUT, # seconds before a delegation is stopped; 0 never
                 subagent_depth=2,          # levels of sub-agents that may delegate again, at most `SUB_DEPTH_MAX`
                 readonly=False,            # withhold every tool that acts
                 readonly_calls=None,       # hard cap on read-only calls, when set
                 max_cost=None,             # dollars the turn model may spend in one turn; None has no limit, and a local model reports none
                 max_tokens=None,           # tokens the turn model may spend in one turn; None has no limit
                 session_max_cost=None,     # dollars the whole session may spend, earlier turns included
                 session_max_tokens=None,   # tokens the whole session may spend, earlier turns included
                 local_multimodal=False,       # load LiteRT vision/audio encoders for local models
                 tool_max_len=None,           # None scales the result cap to the model window
                 on_compact=None,
                 on_activity=None,
                 history_name='agent',      # names this durable conversation in the config dir
                 session_id=None,           # this session's id, for a host that keeps its own; None makes a new one
                 keep_conversation=False,   # save the turn model's whole conversation each turn, for `resume_session(full=True)`
                 poll_every=POLL_EVERY,     # seconds between automatic watch polls; 0 never polls
                 verify='',                 # the project's check; empty reads `[tool.ramabana] verify`
                 instruction_style='ramabana', # 'ramabana' | 'aai' compatibility profile
                 optin=(),                  # shalya's opt-in tool groups, see `OPTIN`
                 profile='auto',            # 'auto', 'small' or 'full'; see `profile_for`
                 warm=None,                 # seed with dhrona's examples; None is off
                 learned=True,              # brief from `<cfg>/learned`; False runs without it
                 fresh_hint=None,           # what a turn too large for any window tells the user to do, `{session}` its id; None suits any host
                 auto_turns=None,           # 'on', 'report' or 'off': whether finished background work starts a turn; None reads `auto_turns`, else `on` under `edits`/`auto` approvals and `report` otherwise
                 auto_turns_per_hour=None): # most automatic turns an hour; None reads `auto_turns_per_hour`, else 6
        self.host, self.cfg, self.inline_skills, self.learned = host, cfg, inline_skills, learned
        if instruction_style not in ('ramabana', 'aai'): raise ValueError('instruction_style must be ramabana or aai')
        if profile not in PROFILES: raise ValueError(f'profile must be one of {", ".join(PROFILES)}, not {profile!r}')
        self.profile_choice = profile
        self.instruction_style, self.optin = instruction_style, tuple([optin] if isinstance(optin, str) else optin)
        if (bad := set(self.optin) - set(OPTIN)): raise ValueError(f'unknown optin {sorted(bad)}; one of {", ".join(OPTIN)}')
        self.history_name = history_name
        self.session_id = session_id or f'agent_{datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")}'
        self.keep_conversation = bool(keep_conversation)
        self.inbox_key = uuid.uuid4().hex[:8]   # stable per session; the briefing stays cached
        self._steered = []
        self.queued = deque()   # prompts held for the turns after this one; `run_queued` runs them
        self.turn_seq, self.current_turn_id = 0, ''
        self.current_branch_id, self.checkpoints, self._branch_hist = 'main', {}, {}
        self.routing = routing or Routing(turn=model)
        if model: self.routing.set(model)
        self.approvals, self.tool_max_len, self.subagents, self.verify = approvals, tool_max_len, subagents, verify
        self._bg_done, self._session_started, self.last_verify = [], False, ''
        self.auto_turns, self.auto_turns_per_hour, self._wakes = auto_turns, ifnone(auto_turns_per_hour, setting('auto_turns_per_hour', 6)), deque()
        self.on_watch = None             # callable(target, log_path), instead of a tmux pane
        self.on_background_done = None   # callable(run, answer)
        self.subagent_writes = bool(subagent_writes)
        self.turn_channel = self.sub_channel = self.sub_effort = ''   # '' takes config.toml's
        self._be_lock = threading.RLock()   # one backend per model, however many delegations ask for it at once
        self.subagent_steps, self.subagent_timeout, self.subagent_depth = _sub_steps(subagent_steps), _sub_timeout(subagent_timeout), _sub_depth(subagent_depth)
        self.sub_slots = Slots()   # one bound on sub-agents at once, across every delegation tree
        self.readonly, self.readonly_calls, self.plan_mode = bool(readonly), readonly_calls, False
        self.max_cost, self.max_tokens, self.session_max_cost, self.session_max_tokens = max_cost, max_tokens, session_max_cost, session_max_tokens
        if any(v is not None for v in (max_cost, max_tokens, session_max_cost, session_max_tokens)):
            self._chat_callbacks = {'budget': _budget_callback(self)}
        self.local_multimodal = bool(local_multimodal)
        self.extensions, self.project_extensions, self.ext_paths = extensions, project_extensions, ext_paths
        self._sp, self.extra_sp, self.global_skills = sp, extra_sp, bool(global_skills)
        self.compactor = Compactor(auto=ifnone(compact, setting('compaction.auto', True)), strategy=ifnone(compact_strategy, setting('compaction.strategy', 'summary')),
                                   kernel_alive=kernel_alive, on_compact=on_compact)
        self.fresh_hint = fresh_hint
        self.activity = Activity(on_change=on_activity)
        self.activity.tap = self._act_event
        self._nested = contextvars.ContextVar('delegating', default=())   # per context; a fan-out's workers inherit it
        self.plan = Plan()
        self.on_plan = None      # callable(plan) after every mutation
        self.on_media = None     # callable(paths) when a tool writes a picture
        self.calls = []
        self.history = []
        self._load_history()
        self._load_plan()
        self.before = {}         # path -> file text before this turn's first write: a notebook's JSON, not its cell text
        self.session_before = {} # the same for the whole session: each path's earliest text, folded in at each turn's start
        self.new = set()         # paths this turn created
        self.binary = set()      # paths whose pre-image would not decode
        self._walked = False
        self._tree = {}
        self._too_big = ()       # the roots whose text is over `SHELL_SNAPSHOT`; commands do not re-read them
        self._scoped = None      # the folders the live snapshot covers, or None for every root
        self._scope_big = set()  # scopes whose text is over `SHELL_SNAPSHOT`, which commands do not re-read
        self._tool_calls_turn = 0
        self.max_tool_calls = 80
        self.use = Usage()       # session total, across every model
        self.turn_use = Usage()  # the last foreground turn; persisted with history
        self._usage_seen = {}
        self.note = 'not started'
        self._backends, self._skills, self._reg, self._tools = {}, None, None, None
        self._catalogs, self._views = {}, {}
        self._catalog_view = ToolCatalog()
        self.poll_every, self._polled, self._poll_thread = float(poll_every or 0), 0.0, None
        self._watch_found, self._watch_lock = [], threading.Lock()
        self.peer_notes, self.peer_waits = [], set()   #: peer notes and replies kept for the next turn; the peers a `tell` waits on for a reply
        self._peer_rows, self._peer_rows_at = [], float('-inf')
        self.turn_ends = []   #: callables given each turn's log row once it is recorded, however the turn ended
        self.git_undo = {}       # turn id -> its git writes and `undo` tokens
        self.warm_choice, self._warmed, self.warm_report = warm, False, {'used': [], 'skipped': []}
        self.on_warm = None      # callable(warm_report) once a session is seeded
