@patch
def _record(self:Agent, f):
    "Wrap one tool so the agent logs its calls and can measure its changes. The `read_only` copy is wrapped too."
    if getattr(f, '_recorded', None) == (self, f): return f   # not a mark `wraps` copied from another wrapper
    name = getattr(f, '__name__', '?')
    if (ks := getattr(f, 'secret_args', ())): SECRET_ARGS[name] = tuple(ks)

    @functools.wraps(f)   # backends build the schema from the real signature
    def wrapper(*a, **kw):
        args = _named(f, a, kw)
        if getattr(current_run(), 'kind', 'root') == 'root':
            self._tool_calls_turn += 1
            if self.max_tool_calls is not None and self._tool_calls_turn > self.max_tool_calls:
                return ('Tool-call budget exhausted for this turn. Stop calling tools and '
                        'summarise the evidence and unfinished work now.')
        elif not self._draw(): return TREE_SPENT
        if (bad := _arg_problem(f, args)): return self._close_act(self._open_act(f, name, args), err(bad))
        denied, rewritten = None, False
        for r in (self._guard(name, args, is_write(f) or path_write(name, args)), *self.registry.fire('before_tool', self, name, args)):
            if isinstance(r, str): denied = denied or r
            elif isinstance(r, dict): a, kw, args, rewritten = (), dict(r), _named(f, (), dict(r)), True
        writing = is_write(f) or path_write(name, args)
        if rewritten: denied = denied or self._guard(name, args, writing) or _arg_problem(f, args)   # the call that runs is the rewritten one
        if rewritten and writing and not denied and self.approvals is not None and not (ask := self.approvals.request(name, args)).answer:
            return err(ask.reply())   # the gate's recorder already logged it
        self.calls.append((name, _hidden(name, args)))
        act = self._open_act(f, name, args)
        if denied:
            self.activity.finish(act, denied, ok=False)
            return err(denied)
        fresh = []
        if writing:
            if (ps := write_targets(name, args)):
                for p in ps:
                    if p in self.before: continue
                    fresh.append(p); was = self._raw_at(p)
                    self.before[p] = was or ''
                    if not self.host.exists(p): self.new.add(p)
                    elif was is None: self.binary.add(p)
            elif name == 'run_shell' or name in GIT_WRITE_TOOLS: self.snapshot_tree(args.get('cwd') or args.get('path') or '', args.get('command') or '')
        nested = name in DELEGATE_TOOLS
        if nested: token = self._nested.set(self._delegating + (act.id,))
        shelled = (name == 'run_shell' or name in GIT_WRITE_TOOLS) and self._walked
        try: out = f(*a, **kw)
        except NotImplementedError as e:
            self.activity.finish(act, agent_err(e), ok=False)
            return err(f'{name} is not available here', e)
        except Exception as e:
            self.activity.finish(act, agent_err(e), ok=False)
            raise
        finally:
            if nested: self._nested.reset(token)
            if shelled: self.settle_tree()
        for r in self.registry.fire('after_tool', self, name, out):
            if isinstance(r, str): out = keep_media(r, out)
        if failed(out):
            for p in fresh: self.before.pop(p, None); self.new.discard(p); self.binary.discard(p)
        if name in GIT_WRITE_TOOLS and not failed(out): self._keep_undo(name, out)
        return self._close_act(act, out)
    wrapper._recorded = (self, wrapper)
    # `wraps` copied `f.read_only`; record it too
    if (ro := getattr(f, 'read_only', None)) is not None: wrapper.read_only = self._record(ro)
    return wrapper


@patch
def _open_act(self:Agent, f, name, args):
    "Start the row for one call, and write it in the transcript of the run that makes the call."
    args = _hidden(name, args)
    act = self.activity.start(name, args, summary=summarise(f, args), **self._action_meta(name, args))
    if (run := current_run()) is not None: run.write(f'> {act.summary}')
    return act

@patch
def _close_act(self:Agent, act, out):
    "Finish `act` with `out`, and return `out`."
    self.activity.finish(act, out, ok=not failed(out))
    if (m := tool_media(out)) and not failed(out): self._drew(m)
    if (run := current_run()) is not None: run.write(f"< {act.tool} {'ok' if not failed(out) else 'ERR'} {_1(out, 200)}")
    return out

@patch
def _observe(self:Agent, f):
    "Show the calls of a read-only sub-agent tool on the activity feed. It runs no hooks and no gate. It applies only the tree's budget."
    name = getattr(f, '__name__', '?')
    if (ks := getattr(f, 'secret_args', ())): SECRET_ARGS[name] = tuple(ks)
    @functools.wraps(f)
    def wrapper(*a, **kw):
        if not self._draw(): return TREE_SPENT
        args = _named(f, a, kw)
        if (bad := _arg_problem(f, args)): return self._close_act(self._open_act(f, name, args), err(bad))
        act = self._open_act(f, name, args)
        if (nested := name in DELEGATE_TOOLS): token = self._nested.set(self._delegating + (act.id,))
        try: out = f(*a, **kw)
        except Exception as e:
            self.activity.finish(act, agent_err(e), ok=False)
            raise
        finally:
            if nested: self._nested.reset(token)
        return self._close_act(act, out)
    if (ro := getattr(f, 'read_only', None)) is not None: wrapper.read_only = self._observe(ro)
    return wrapper


@patch
def _draw(self:Agent):
    "Count a sub-agent's call against its budget. With a numeric `max_tool_calls`, the budget is the turn's tool-call budget. Under `auto` (`max_tool_calls` None), each delegation has its own budget of `4 * SUB_STEP_CEILING` calls. Returns False once the budget is spent."
    run = current_run()
    # under auto the turn is uncapped; one shared pool would starve later delegations
    return run is None or run.draw(ifnone(self.max_tool_calls, 4 * SUB_STEP_CEILING), per_branch=self.max_tool_calls is None)

@patch
def _deny_git_shell(self:Agent, name, args):
    "Refuse a `run_shell` line that does what a git tool does. Returns the reason, or None."
    return git_shell_denial(args.get('command', ''), {t.__name__ for t in self.tools}) if name == 'run_shell' else None


HIDING = {'head', 'tail'}   #: commands a pipe may not end in, because they cut output before anyone reads it
READERS = {'cat', 'less', 'more', 'head', 'tail', 'grep', 'tac', 'nl', 'strings'}   #: commands refused on a `.env` file, because they print its values
ASK_PRESENCE = 'ask whether one variable is set instead: `test -n "$NAME" && echo set`'
#: commands that run the command after them, with their options that take a value
_ENV_WRAPS = {'env': ('-u', '--unset', '-C', '--chdir'), 'sudo': ('-u', '-g'), 'nice': ('-n', '--adjustment'), 'nohup': (), 'time': (), 'command': (),
              'exec': ('-a',), 'builtin': (), 'xargs': ('-n', '-I', '-L', '-P', '-s', '-d', '-E', '-a', '--max-args', '--arg-file'), 'stdbuf': (), 'setsid': (),
              'timeout': ('-k', '-s', '--kill-after', '--signal')}

def _dotenv(w):
    "Whether `w` names a `.env` file that holds values: `.env` or `.env.local`, not a template such as `.env.example`."
    n = Path(w).name
    return n == '.env' or (n.startswith('.env.') and n.rsplit('.', 1)[-1] not in ('example', 'sample', 'template', 'dist', 'md'))

def env_denial(command):
    "Why a shell line prints environment values, which hold API keys, or ''. Quoted text never matches. A `sh -c` line is checked too."
    for seg in _segments(command):
        groups, cur = [], []
        for w in seg:   # `$(printenv X)` and `( env )` are commands of their own; `$HOME/.env` is one word
            if w in ('(', ')', '{', '}'): groups.append(cur); cur = []
            elif w != '$': cur.append(w)
        for words in groups + [cur]:
            if (p := next((w for w in words if re.fullmatch(r'/proc/[^/]+/environ', w)), None)): return f'`{p}` holds a process environment; {ASK_PRESENCE}'
            while words and (_NAMEVAL.fullmatch(words[0]) or (Path(words[0]).name in _ENV_WRAPS and not (words[0] == 'command' and words[1:2] in (['-v'], ['-V'])))):   # `command -v env` only looks
                w0, inner = ('' if _NAMEVAL.fullmatch(words[0]) else Path(words[0]).name), words[1:]
                while inner and (inner[0].startswith('-') or (w0 == 'env' and _NAMEVAL.fullmatch(inner[0]))):
                    inner = inner[2:] if inner[0] in _ENV_WRAPS.get(w0, ()) else inner[1:]
                if w0 == 'timeout': inner = inner[1:]   # its duration
                if w0 == 'env' and not inner: break   # `env` with nothing to run prints the environment
                words = inner
            if not words: continue
            head, rest = Path(words[0]).name, words[1:]
            flags = ''.join(w[1:] for w in rest if re.fullmatch(r'-[a-zA-Z]+', w))
            if (head == 'printenv' or (head == 'env' and rest not in (['--help'], ['--version'])) or (head == 'set' and not rest) or (head == 'export' and rest in ([], ['-p']))
                or (head in ('declare', 'typeset') and (not rest or 'p' in flags or ('x' in flags and all(w.startswith('-') for w in rest))))):
                return f'`{shlex.join(words)}` prints environment values, which hold API keys; {ASK_PRESENCE}'
            if head in READERS and (f := next((w for w in rest if _dotenv(w)), None)): return f'`{head} {f}` prints a file of secrets; {ASK_PRESENCE}'
            if head in _SHELLS and (i := next((i for i, w in enumerate(rest) if re.fullmatch(r'-[a-zA-Z]*c', w)), -1)) >= 0 and i + 1 < len(rest):
                if (why := env_denial(rest[i + 1])): return why
    return ''

def shell_denial(command):
    "Why a shell line hides its own output or prints environment values, or ''. Quoted text never matches. A `sh -c` line is checked too."
    if (why := env_denial(command)): return why
    try: toks = list(shlex.shlex(str(command or ''), posix=True, punctuation_chars=True))
    except ValueError: return ''
    for i, t in enumerate(toks):
        nxt = toks[i + 1:i + 3]
        if t in ('|', '|&') and nxt and Path(nxt[0]).name in HIDING:
            return (f'`| {nxt[0]}` cuts the output a failure is in. Run the command bare, or redirect stdout '
                    'and stderr to separate files and read both')
        if t == '2' and nxt == ['>&', '1']:
            return '`2>&1` merges stderr into stdout. Leave them apart, so a crash stays visible'
        if i and re.fullmatch(r'-[a-zA-Z]*c', t) and Path(toks[i - 1]).name in _SHELLS and i + 1 < len(toks):
            if (why := shell_denial(toks[i + 1])): return why
    return ''

_GENERATED = re.compile(r'AUTOGENERATED! DO NOT EDIT! File to edit: (\S+?)\.?$', re.M)

def generated_denial(host, name, args):
    "Why a write would hand-edit an nbdev-generated module, or ''."
    for p in write_targets(name, args):
        if (m := _GENERATED.search((host.text_at(p) or '')[:300])):
            return f'{p} is generated from {m.group(1)}. Edit that notebook, then run `nbdev-export`'
    return ''

PEER_ROWS_EVERY = 10   #: seconds the folder guard keeps the list of live peers
PEER_ROWS_WAIT = .3    #: seconds each peer has to answer `status` when the folder guard reads the list

def _full(host, p):
    "`p` as `host` resolves it; a path the host refuses is taken from its first root."
    try: return host.check(p)
    except HostError: return Path(host.roots[0])/p

@patch
def peer_denial(self:Agent, name, args):
    "Why a write would change a folder that another live session holds and this one does not, or ''."
    if self.cfg is None or not (paths := write_targets(name, args)): return ''
    if time.monotonic() - self._peer_rows_at > PEER_ROWS_EVERY:
        self._peer_rows, self._peer_rows_at = all_peers(self.cfg, self.session_id, PEER_ROWS_WAIT), time.monotonic()
    me = f'ramabana-{self.session_id}'
    rows = [*self._peer_rows, {'key': me, 'folders': [str(r) for r in self.host.roots], 'guard': guard_of(self.host.roots)}]
    return next(filter(None, (folder_denial(_full(self.host, p), me, rows) for p in paths)), '')

@patch
def _guard(self:Agent, name, args,
           writing=False):   # whether this call writes where it names; a write to a generated module is refused
    "Why a call is refused before it runs, or None. Git writes go through git tools. Shell output is read whole and never dumps the environment. Write tools leave generated modules to their notebooks, never write `[SECRET]` over a real key, and stay out of another live session's folders."
    if name in ('run_shell', 'run_shell_bg'): return self._deny_git_shell(name, args) or shell_denial(args.get('command', '')) or None
    return (generated_denial(self.host, name, args) or secret_denial(self.host, name, args) or self.peer_denial(name, args) or None) if writing else None


@patch
def _keep_undo(self:Agent, name, out):
    "Store the `undo` token, resulting HEAD and repository root of a git write under this turn, for `/rewind`."
    try: d = json.loads(out)
    except Exception: return
    if not isinstance(d, dict): return
    self.git_undo.setdefault(self.current_turn_id, []).append({k: str(d.get(k) or '') for k in ('summary', 'undo', 'undoes', 'head', 'branch', 'root')} | {'tool': name})
    if (cd := self.checkpoint_dir) is not None:
        cd.mkdir(parents=True, exist_ok=True)
        (cd/f'{self.current_turn_id}.git.json').write_text(json.dumps(self.git_undo[self.current_turn_id]))

