@patch(as_prop=True)
def _quiet(self:Agent):
    "Whether the text of the turn model between calls does not reach the user. Such a model reports its status with a tool."
    return getattr(self.spec_or_none('turn'), 'runtime', '') in QUIET_RUNTIMES

@patch(as_prop=True)
def tools(self:Agent):
    "Every tool the turn model can afford, built once and recorded. `reload` rebuilds it."
    if self._tools is None:
        view = self._catalog_for(self.budget, profile=self.profile)
        if self.readonly or self.plan_mode:
            view = view.read_only(self.readonly_calls, effects=False, block=NO_SUB)
        self._catalog_view = view
        if self.approvals is not None:
            self.approvals.tools = self.approvals.tools | view.writes
            self.approvals.prune()
        root = lambda: r if (r := current_run()) is self.run() else None
        self._tools = view.map(lambda f: _inboxed(self._record(f), root, self._heard_steer, mx=lambda: self.budget.tool_max)).tools + ([status_tool(root)] if self._quiet else [])
    return self._tools




