MEMORY_CHARS = 4000

@patch(as_prop=True)
def memory_path(self:Agent):
    "`<cfg>/memory/<root hash>/MEMORY.md`: this project's notes, kept without a vault."
    if self.cfg is None or not self.host.roots: return None
    return self.cfg/'memory'/hashlib.sha1(str(self.host.roots[0]).encode()).hexdigest()[:12]/'MEMORY.md'

@patch
def note_memory(self:Agent, text, title='', tags='', key=''):
    "Write `- [key] **title**: text` to the project's memory file. A line with the same `key` is replaced."
    p = self.memory_path
    if p is None: return 'no config directory to remember into'
    p.parent.mkdir(parents=True, exist_ok=True)
    line = '- ' + (f'[{key}] ' if key else '') + (f'**{title}**: ' if title else '') + ' '.join(str(text).split())
    lines = p.read_text().splitlines() if p.exists() else []
    had = [i for i, l in enumerate(lines) if key and l.startswith(f'- [{key}] ')]
    if had: lines[had[0]] = line
    else: lines.append(line)
    p.write_text('\n'.join(lines) + '\n')
    return f'{"replaced" if had else "remembered"} in {p}'

@patch
def memory_context(self:Agent, surface, max_chars=MEMORY_CHARS):
    "The project's memory file, or its last `max_chars` characters when it is long. An embedder with a vault overrides this method."
    p = getattr(self, 'memory_path', None)
    return p.read_text()[-max_chars:] if p is not None and p.exists() else ''

@patch
def lessons(self:Agent, limit=50):
    "The lessons `remember` kept for this project, from the vault or the memory file. Returns an empty list with learning off."
    if not self.learning: return []
    if 'memory' in self.host.provides:
        try: rows = self.host.memory_search('lesson:', limit)
        except Exception: return []
        rows = (rows.get('results') or []) if isinstance(rows, dict) else rows   # a vault's context: sections under `results`
        text = '\n\n'.join(f"{r.get('title') or ''}\n{r.get('text') or ''}" if isinstance(r, dict) else str(r) for r in rows)
        return list({l['lesson']: l for l in lesson_rows(text)}.values())[:limit]   # a title can repeat its note's first line
    p = self.memory_path
    return lesson_rows(p.read_text())[-limit:] if p is not None and p.exists() else []

def note_tools(note, learning=lambda: True):
    "The memory tool for a host without a vault: shalya's `remember`, writing to the project's memory file."
    @summary(lambda a: f'Remember {_1(a.get("title") or a.get("text"), 80)}')
    def remember(text: str,             # the conclusion to keep, in a sentence or two
                 title: str = '',       # a short heading for it
                 tags: str = '',        # comma-separated words to find it by
                 key: str = '',         # a stable name; a later note with the same key replaces this one
                 cue: str = '',         # for a lesson: the situation that should bring it to mind
                 component: str = '',   # for a lesson: rule, skill, extension, tool or memory
                 evidence: str = '',    # for a lesson: what showed the mistake
                 confidence: str = '',  # for a lesson: low, medium or high
                 ) -> str:
        "Store a conclusion in this project's memory file (no vault here); the same `key` later replaces the line; a lesson from a mistake adds `cue`, `component` (rule, skill, extension, tool or memory), `evidence` and `confidence` (low, medium or high)."
        if not learning(): cue = component = evidence = confidence = ''
        try: body = lesson_text(text, cue, component, evidence, confidence)
        except ValueError as e: return err('could not remember', e)
        if body != text: body = ' | '.join(body.splitlines())   # the memory file holds one line per note
        return note(body, title=title, tags=tags, key=key)
    return [remember]

