@patch
def start(self:Agent):
    "Build the turn backend, once. Returns it, or None with `note` explaining why not."
    b = self._be('turn')
    if (k := missing_key(b.spec)):
        self.note = f'turn job: {b.spec.name} {needs(k)}. {SETUP_HINT}'
        return None
    if (m := missing_runtime(b.spec)):
        self.note = f'turn job: {b.spec.name} cannot run here: {m}. {reachable_hint()}'
        return None
    if getattr(b.spec, 'missing', ''): b.spec = replace(b.spec, missing='')
    if b.start() is None:
        self.note = b.note
        return None
    self.note = f'{model_note(b.spec)} · {len(self.tools)} tools'
    if self.profile == 'small' and self.profile_choice == 'auto' and not getattr(self, '_profile_noted', False):
        self._profile_noted = True
        self.host.note(f"small profile: {b.spec.name} is {'local' if b.spec.local else '≤32k'} — {len(self.tools)} tools, warm start {'on' if self.warm else 'off'}; --profile full for everything")
    return b

