@patch
def set_model(self:Agent, name, job='turn'):
    "Point `job` at `name`. Changing the turn model moves the live conversation to the new model. Raises `RuntimeError` while a turn runs."
    if self.busy: raise RuntimeError('cannot change model while the assistant is working')
    previous = self.spec_or_none(job)
    old = previous and (previous.backend, previous.model_id)
    history = self._backends[old].snapshot_hist() if job == 'turn' and old in self._backends else []
    before = (self.budget, self.profile)
    spec = self.routing.set(name, job)
    new = (spec.backend, spec.model_id)
    if job == 'turn' and ((self.budget, self.profile) != before or new != old): self._tools = None
    if job == 'subagent': self._catalogs.clear(); self._views.clear()
    if job == 'turn' and new != old:
        self._be('turn').resume_hist(history)
    still_used = {(s.backend, s.model_id) for j in JOBS if (s := self.spec_or_none(j))}
    if old not in still_used and old in self._backends:
        self._backends.pop(old).close()
    self.note = f'{job} → {model_note(spec)}' + (f' · {self.profile} profile' if job == 'turn' else '')
    return spec

@patch
def settle(self:Agent):
    "Move a turn that nobody named off a model that cannot run here, onto `Routing.settled()`. Returns the line that says so, or ''."
    was = self.routing.turn
    if not (alt := self.routing.settled()): return ''
    why = needs_setup(self.routing)
    self.set_model(alt)
    self.routing.picked.discard('turn'); self.routing.named = False   # a stand-in; config.toml can still name the turn
    return f'{was} cannot run here ({why.split(";")[0]}), so this session runs on {alt}, the model ready here · /model to change it, /login to add another'

@patch
def apply_config(self:Agent):
    "Read config.toml's `[jobs]` again for every job this session has not set itself. Returns one line per job that moved."
    out, r = [], self.routing
    for job in JOBS:
        if job in r.picked or (job == 'turn' and r.named): continue
        before = r.name_for(job)
        if job == 'turn':
            want = setting('jobs.turn') or (DFLT_TURN if not r._why(DFLT_TURN) else '')   # a turn config.toml no longer names goes back to the default
            if not want or want == before: continue
            if (why := r._why(want)): out.append(f'turn stays on {before}: {want} {why.split(";")[0]}'); continue
            try: self.set_model(want)
            except Exception as e: out.append(f'turn stays on {before}: {agent_err(e)}'); continue
            r.picked.discard('turn'); r.named = False
        elif r.unset(job) == before: continue
        if job == 'subagent': self._catalogs.clear(); self._views.clear()
        out.append(f'{job} → {r.name_for(job)}')
    return out

@patch
def config_command(self:Agent, arg=''):
    "`/config`: `show` what is in effect, its `path`, `set KEY VALUE`, `reset` to the commented template, or `reload` after an edit by hand."
    cmd, _, rest = (arg.strip() or 'show').partition(' ')
    if cmd == 'show': return config_show()
    if cmd == 'path': return str(config_path())
    try:
        if cmd == 'set':
            key, _, raw = rest.strip().partition(' ')
            if not raw.strip(): return 'say /config set KEY VALUE; /config shows every key'
            said = config_set(key, raw.strip())
        elif cmd == 'reset': said = config_reset()
        elif cmd == 'reload': said = f'read {config_path()}'
        else: return 'say /config [show | path | set KEY VALUE | edit | reset | reload]'
    except (ValueError, OSError) as e: return str(e)
    return '\n'.join([said, *self.apply_config()])

