WARM_ROUNDS = 3   #: dhrona rounds seeded into a fresh session
WARM_SMALL_CHARS = 2500   #: max chars of the small profile's one round

@patch(as_prop=True)
def warm(self:Agent):
    "Whether a fresh session is seeded. It is seeded only when asked, because each round shows one call per message and a model copies it."
    return bool(self.warm_choice)

@patch
def warm_start(self:Agent):
    "Seed a fresh chat with dhrona's accepted rounds whose calls bind to the offered tools."
    if self._warmed: return []
    if not self.warm: return []
    b = self._be('turn')
    small = self.profile == 'small'
    if b.hist or b._resume_hist or not (self.budget.inline or small): return []   # an empty pending restore is still fresh
    self._warmed = True
    try: from dhrona.core import fit_rounds, round_msgs
    except ImportError:
        self.host.note('no warm start: dhrona is not installed (uv add "ramabana[dhrona]")'); return []
    try: used, skipped = fit_rounds(self._plain, model=b.spec.name, limit=1 if small else WARM_ROUNDS)
    except Exception as e:
        self.warm_report = {'used': [], 'skipped': [], 'problem': agent_err(e)}
        self.host.note(f'no warm start: {agent_err(e)}'); return []
    if small and used and (size := len(json.dumps(round_msgs(used[0])))) > WARM_SMALL_CHARS:
        skipped.insert(0, (used.pop(), f'{size} chars is over the small profile limit of {WARM_SMALL_CHARS}'))
    self.warm_report = {'used': [{'name': r['meta'].get('name', ''), 'rank': r['meta'].get('rank', 50), 'model': r['meta'].get('model')} for r in used],
                        'skipped': [{'name': r['meta'].get('name', ''), 'reason': why} for r, why in skipped]}
    msgs = [m for r in used for m in round_msgs(r)]
    if msgs: b.resume_hist(msgs)
    line = f"warm start: {len(used)} round(s) used ({', '.join(r['name'] for r in self.warm_report['used']) or 'none'}), {len(skipped)} skipped"
    self.host.note(line)
    if (run := current_run()) is not None: run.write(line)
    if self.on_warm is not None:
        try: self.on_warm(self.warm_report)
        except Exception: pass
    return msgs

