def repo_state(folder):
    "`{folder, repo, head, branch, dirty}` for the git repository holding `folder`, or None outside one. `dirty` lists modified tracked files."
    from gheasy.repo import GitRepo
    try: r = GitRepo.at(folder); head = r.run('rev-parse', 'HEAD').strip()
    except Exception: return None
    lines = r.run('status', '--porcelain', '--untracked-files=no').splitlines()
    return dict(folder=str(folder), repo=str(r.root), head=head, branch=r.run('branch', '--show-current').strip(),
                dirty=sorted(l[3:].split(' -> ')[-1] for l in lines if len(l) > 3))

@patch
def _record_start(self:Agent):
    "Write each open folder's `repo_state` to `<runs_dir>/start.json` before a session's first turn. A session with turns already began elsewhere and writes none. With learning off, nothing is written."
    d = getattr(self, 'runs_dir', None)
    if d is None or not self.learning or (p := d/'start.json').exists() or self.session_turns(self.session_id): return
    d.mkdir(parents=True, exist_ok=True)
    with atomic_save(p, 'w') as f: json.dump([s for r in self.host.roots if (s := repo_state(r))], f, indent=1)

@patch
def _begin_turn(self:Agent, run=None):
    "Set the identity of this turn before anything can fail: the turn id, the activity mark, the `turn_start` event and the pending-turn file."
    rid = getattr(run, 'id', '')
    if rid and getattr(self, '_begun', None) == rid: return self.current_turn_id
    self._begun = rid
    self.turn_use = Usage()
    self._budget_hit = ''
    self._tool_calls_turn = 0
    self._steered = []
    self.turn_seq += 1
    self.current_turn_id = f'{self.session_id}:turn_{self.turn_seq:06d}'
    self.activity.mark(self.current_turn_id)
    self._event('turn_start', turn_id=self.current_turn_id, prompt=str(request_text(getattr(run, 'question', '')))[:2000],
                model=getattr(self.spec_or_none(), 'name', ''))
    if (d := getattr(self, 'runs_dir', None)) is not None:   # the turn in flight, for a process that dies before its row
        d.mkdir(parents=True, exist_ok=True)
        self.claim_session()
        (d/PENDING).write_text(json.dumps({'prompt': str(getattr(run, 'question', '') or ''), 'at': time.time(), 'pid': os.getpid(),
                                           'turn_id': self.current_turn_id, 'model': getattr(self.spec_or_none(), 'name', '')}))
    return self.current_turn_id


OWNER = 'owner.json'    #: in a session's run folder: the folders it was last used with
LOCK = 'owner.lock'     #: in a session's run folder: the process using it, created exclusively
PENDING = 'turn.json'   #: in a session's run folder: the turn in flight, until its row is written

def _alive(pid):
    "Whether process `pid` is running; 0 or nothing never is."
    try: pid = int(pid or 0)
    except (TypeError, ValueError): return False
    if pid <= 0: return False
    try: os.kill(pid, 0)
    except PermissionError: return True
    except OSError: return False
    return True

def _read_json(p):
    "The JSON in `p`, or None when it is missing or unreadable."
    try: return json.loads(Path(p).read_text())
    except Exception: return None

def _pid_in(p):
    "The process id written in `p`, or 0."
    try: return int(Path(p).read_text().strip() or 0)
    except (OSError, ValueError): return 0

def _claim(d):
    "Take run folder `d` for this process; False when another live process holds it. A dead holder's lock is replaced."
    lock = Path(d)/LOCK
    lock.parent.mkdir(parents=True, exist_ok=True)
    mine = lock.with_name(f'{LOCK}.{os.getpid()}')
    mine.write_text(str(os.getpid()))
    try:
        for _ in range(2):
            try:
                os.link(mine, lock)   # atomic, and the lock holds its pid from the moment it exists
                return True
            except FileExistsError:
                holder = _pid_in(lock)
                if holder == os.getpid(): return True
                if _alive(holder): return False
                lock.unlink(missing_ok=True)
        return False
    finally: mine.unlink(missing_ok=True)

@patch
def claim_session(self:Agent):
    "Hold this session for this process and record its folders; False when another live process holds it."
    if (d := getattr(self, 'runs_dir', None)) is None: return True
    if not _claim(d): return False
    (d/OWNER).write_text(json.dumps({'roots': [str(r) for r in self.host.roots], 'at': time.time()}))
    return True

@patch
def release_session(self:Agent):
    "Give the session up if this process holds it. Its folders stay, for `latest`."
    if (d := getattr(self, 'runs_dir', None)) is not None and _pid_in(d/LOCK) == os.getpid(): (d/LOCK).unlink(missing_ok=True)

@patch
def session_owner(self:Agent, sid):
    "`{'pid': ...}` when another live process holds session `sid`, else None."
    pid = 0 if self.cfg is None else _pid_in(self.cfg/'runs'/str(sid)/LOCK)
    return {'pid': pid} if pid and pid != os.getpid() and _alive(pid) else None

@patch
def _from_here(self:Agent, sid):
    "Whether session `sid` ran with one of this host's folders: those its index entry saved, else those its last holder recorded."
    roots = self.session_meta(sid).get('roots') or ((None if self.cfg is None else _read_json(self.cfg/'runs'/str(sid)/OWNER)) or {}).get('roots') or ()
    return bool({str(r) for r in self.host.roots} & set(roots))

@patch
def _prepare(self:Agent, prompt):
    "Everything that happens before a message goes out: notices, hooks, and prospective compaction."
    for p, was in self.before.items(): self.session_before.setdefault(p, was)
    self.before.clear(); self.new.clear(); self.binary.clear()
    self._drawn = []
    self._walked, self._tree = False, {}
    self._begin_turn(current_run())
    seeded = []
    if not self._session_started:   # before the checkpoint; /rewind keeps the seeds
        self._session_started = True
        self._record_start()
        seeded = self.warm_start()
        self.registry.fire('session_start', self)
    self.checkpoints[self.current_turn_id] = {'before': self._be('turn').snapshot_hist(),
                                              'branch_id': self.current_branch_id}
    for old in list(self.checkpoints)[:-MAX_CHECKPOINTS]: self.checkpoints.pop(old, None)
    self.registry.fire('before_turn', self, prompt)
    self.poll_watches()
    reviews = self.monitors.drain()
    self.poll_monitors()
    outgoing = _with_notices(prompt) if self.instruction_style == 'aai' else prompt
    request = request_text(prompt)
    requested, loaded = prompt_directives(request, self.tools, self.skills)
    names = ', '.join(dict.fromkeys(name for name, _ in requested))
    plan = f'The user explicitly selected these tools: {names}. Use them before completing the task.' if requested else ''
    self._turn_plan = {'route': 'explicit' if requested else 'model', 'text': plan,
                       'tools': [name for name, _ in requested],
                       'skills': [skill.name for skill in loaded]}
    if seeded: self._turn_plan['warm'] = [r['name'] for r in self.warm_report['used']]
    eager = {'search_code', 'web_search', 'research', 'memory_search'}
    preflights = [(name, query or request) for name, query in requested if name in eager]
    by_name = {getattr(t, '__name__', ''): t for t in self.tools}
    if plan: outgoing = _append(outgoing, f'\n\n<tool-plan route="explicit">{plan}</tool-plan>')
    for name, query in dict.fromkeys(preflights):
        tool = by_name.get(name)
        if tool is None: continue
        try: evidence = tool(query)
        except Exception as e: evidence = f'{name} failed: {agent_err(e)}'
        outgoing = _append(outgoing, f'\n\n<preflight-tool name="{name}">\n{evidence}\n</preflight-tool>')
    if reviews: outgoing = _append(outgoing, review_notice(reviews))
    if (done := self.background_notice()): outgoing = _append(outgoing, done)
    if (fired := self.watch_notice()): outgoing = _append(outgoing, fired)
    if (heard := self.peer_notice()): outgoing = _append(outgoing, heard)
    if (left := self.beat_drain()): outgoing = _append(outgoing, beat_notice(left))
    for skill in loaded:
        outgoing = _append(outgoing, f'\n\n<requested-skill name="{skill.name}">\n{skill.text()}\n</requested-skill>')
    return self._fit(outgoing, _grown(outgoing, prompt))

FRESH_HINT = 'Start a new conversation for a fresh window; this one stays in the history and can be resumed.'   #: `ContextFull`'s advice when the host gives none

def _grown(outgoing, prompt):
    "How many characters `_prepare` added to the end of the last text of the prompt. An excerpt keeps these reminders whole."
    last = lambda m: next((p for p in reversed(m) if isinstance(p, str)), '') if isinstance(m, (list, tuple)) else str(m or '')
    return max(0, len(last(outgoing)) - len(last(prompt)))

@patch
def _fit(self:Agent, outgoing, tail=0):
    "Make `outgoing` fit the turn model's window. Oversized content is cut to an excerpt, and the whole text is kept in a file. Raises `ContextFull` only when the briefing and tools alone are too large."
    b = self._be('turn')
    cold = math.ceil(margin()*b.count_tokens(b.sp)) if b.chat is None else 0   # an unstarted chat counts nothing yet, its briefing included
    if not b.spec.ctx or b.fits(outgoing, reserve=min(1024, max(128, b.spec.ctx // 4)) + cold): return outgoing
    if b.start() is None: return outgoing   # a model that cannot start says so when the turn goes out
    b.spill, b.how = self._spill, self._how()
    limit = max(1, b.spec.ctx - min(1024, max(128, b.spec.ctx // 4)))   # `fits`'s line
    half = int((limit - margin()*b.base_tokens()) / margin() / 2)
    if not b.fits(outgoing):
        # a paste past half the room is cut first; a notebook has its own cutting
        if not (isinstance(outgoing, str) and '<notebook' in outgoing) and b.pending_tokens(outgoing) > half:
            outgoing = fit_content(outgoing, max(64, half), b.spill, b.how, b.count_tokens, tail)
        # a newest exchange past it is cut too, not summarised away
        if (big := sum(msg_tokens(m, b.count_tokens) for m in b.hist[-2:] if m.get('role') in ('user', 'tool'))) > half: b.shrink_recent(big - half)
    if not b.fits(outgoing): b.trim(b.projected_tokens(outgoing) - (threshold(b.spec.ctx, self.compactor.reserve) or b.spec.ctx))   # oldest tool results and pictures first
    if (self.compactor.auto and self.compactor.due(b)) or not b.fits(outgoing): self.compact()
    if not b.fits(outgoing): outgoing = compact_notebook_context(outgoing, b.fits)
    if not b.fits(outgoing): b.shrink_recent(b.projected_tokens(outgoing) - limit)
    for k in range(4):
        if b.fits(outgoing): return outgoing
        outgoing = fit_content(outgoing, max(64, int(((limit - b.used_tokens) / margin() - 8) * .8**k)), b.spill, b.how, b.count_tokens, tail)
    if b.fits(outgoing): return outgoing
    raise ContextFull(f'this conversation does not fit {b.spec.name}: about {b.projected_tokens(outgoing):,} tokens with this message, '
                      f'past its {b.spec.ctx:,}-token window, even with the message cut to an excerpt; the briefing and tools alone take about '
                      f'{math.ceil(margin()*b.base_tokens()):,}. ' + (self.fresh_hint or FRESH_HINT).replace('{session}', self.session_id))

@patch
def _spill(self:Agent, data, suffix='.txt'):
    "Keep `data` whole in `<runs_dir>/full`, readable by this user alone. Returns its path, or None."
    try:
        p = self._full_dir()/f'{datetime.datetime.now():%H%M%S}-{uuid.uuid4().hex[:8]}{suffix}'
        with os.fdopen(os.open(p, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), 'wb') as f: f.write(data)
        return p
    except OSError: return None

@patch
def _full_dir(self:Agent):
    "Where cut content is kept: `<runs_dir>/full`, else a private temp folder. The folder is opened read-only to the read tools when they cannot reach it."
    held = getattr(self, '_full', None)
    if held and held[0] == self.runs_dir: return held[1]
    d = self.runs_dir/'full' if self.runs_dir is not None else Path(tempfile.mkdtemp(prefix='ramabana-full-'))
    d.mkdir(parents=True, exist_ok=True, mode=0o700)
    try: self.host.check(str(d), reading=True)
    except Exception:
        try: self.host.sandbox.add_root(str(d), readonly=True)
        except Exception: pass
    self._full = (self.runs_dir, d)
    return d

@patch
def _how(self:Agent):
    "How the model reads a kept file back, from the tools it has."
    names = {getattr(t, '__name__', '') for t in self.tools}
    if 'view_file' in names: return 'read it in pieces with view_file(path, start=N)' + (', or search it with grep' if 'grep' in names else '')
    if 'run_shell' in names: return 'read it in pieces with run_shell'
    return 'ask the user for the part you need'


