REPLAYED = ('complete', 'failed')

def _replaced(f, p):
    "Whether `p` is no longer the file `f` holds open: another process renamed a new one over it."
    try: return os.fstat(f.fileno()).st_ino != os.stat(p).st_ino
    except FileNotFoundError: return True

def _append_line(p, line):
    "Append one line to `p` under an exclusive lock. Lines from two processes never interleave. Returns the byte span of the line."
    import fcntl
    data = line.encode()
    while True:
        with open(p, 'ab') as f:
            fcntl.flock(f, fcntl.LOCK_EX)
            try:
                if _replaced(f, p): continue   # queued on a file `compact_history` has since replaced
                f.write(data); f.flush()
                end = f.tell()
            finally: fcntl.flock(f, fcntl.LOCK_UN)
        return end - len(data), end

EVENT_MAX = 10_000_000   #: bytes an event file reaches before it is renamed to `<name>.1` and started again
HIST = 'hist.json'   #: in a session's run folder: the turn model's whole conversation as its last turn left it

def _whole(hist):
    "`hist` up to its last complete exchange. The provider refuses a call that a stop left without its result."
    answered = {m.get('tool_call_id') for m in hist if isinstance(m, dict) and m.get('role') == 'tool'}
    for i in range(len(hist) - 1, -1, -1):
        m = hist[i]
        if isinstance(m, dict) and m.get('role') == 'assistant' and any(tc.get('id') not in answered for tc in m.get('tool_calls') or ()):
            return list(hist[:i])
    return list(hist)

def _scrub(hist):
    "`hist` with the secret arguments of each tool call as `[SECRET]`."
    def one(c):
        fn = c.get('function') or {}
        if not SECRET_ARGS.get(n := tc_name(c)): return c
        return c | {'function': fn | {'arguments': json.dumps(_hidden(n, parse_args(fn.get('arguments'))), ensure_ascii=False)}}
    return [m | {'tool_calls': [one(c) for c in m['tool_calls']]} if isinstance(m, dict) and m.get('tool_calls') else m for m in hist]

@patch
def _save_hist(self:Agent):
    "Keep the turn model's whole conversation, tool results included, for `resume_session(full=True)`, when `keep_conversation` asks."
    if not self.keep_conversation or (d := getattr(self, 'runs_dir', None)) is None: return
    try:
        b = self._be('turn')
        data = json.dumps({'turn_id': self.current_turn_id, 'backend': b.spec.backend, 'model_id': b.spec.model_id,
                           'hist': _scrub(_whole(b.snapshot_hist()))}, ensure_ascii=False)
        d.mkdir(parents=True, exist_ok=True)
        with atomic_save(d/HIST, 'w') as f: f.write(data)
    except Exception as e: self.history_problem = f'the conversation was not saved for a full resume ({agent_err(e)})'

@patch
def events_to(self:Agent, path,
              max_bytes=EVENT_MAX):   # the size at which the file rolls over to `<name>.1`
    "Write one JSON line per event to `path` from now on: calls, asks, plan changes, turns and steering. Returns the path."
    p = Path(path).expanduser()
    p.parent.mkdir(parents=True, exist_ok=True)
    os.close(os.open(p, os.O_CREAT | os.O_APPEND | os.O_WRONLY, 0o600))   # prompts and tool output are this user's to read
    if '_event_lock' not in self.__dict__: self._event_lock = threading.Lock()
    self.__dict__.setdefault('_event_files', []).append((p, int(max_bytes)))
    return p

@patch
def _event(self:Agent, kind, **data):
    "Append one event to every file `events_to` named. A failed write never reaches the turn."
    if not (files := self.__dict__.get('_event_files')): return
    line = json.dumps({'at': time.time(), 'session': self.session_id, 'kind': kind, **data}, ensure_ascii=False, default=str) + '\n'
    with self._event_lock:   # threads in this process rotate one at a time; other processes may still race a rotation
        for p, mx in files:
            try:
                if p.exists() and p.stat().st_size + len(line.encode()) > mx: p.replace(p.with_name(p.name + '.1'))
                _append_line(p, line)
            except Exception: pass

@patch(as_prop=True)
def details_path(self:Agent):
    "`<cfg>/<history_name>-details/<session>.jsonl`: tool results too long for the turn log, or None without a config dir."
    return None if self.cfg is None else self.cfg/f'{self.history_name}-details'/f'{self.session_id}.jsonl'

ROW_MAX = 1_000_000   #: bytes a log row may reach; a slimmed row past it sends its prompt to the details file too

_CUT = re.compile(r'\n…\[\d+ more chars\]$')

def _cut(detail):
    "Whether `detail` is a result that `_clip` already cut to `RESUME_DETAIL`. Such a result has the cut length plus the marker."
    return (m := _CUT.search(detail)) is not None and len(detail) == RESUME_DETAIL + len(m.group())

def _long_details(turn):
    "The results in `turn`'s activity over `RESUME_DETAIL` that `_clip` has not already cut to it, by call id."
    return {a['id']: a['detail'] for a in turn.get('activity') or () if a.get('id') and len(d := a.get('detail') or '') > RESUME_DETAIL and not _cut(d)}

def _clipped(turn, long, ref):
    "`turn` with each result in `long` cut to its start and `ref`, the details file, named."
    acts = [a | {'detail': _clip(a['detail'], RESUME_DETAIL)} if a.get('id') in long else a for a in turn['activity']]
    return turn | {'activity': acts, 'details': ref}

@patch
def _slim(self:Agent, turn):
    "`turn` as the log keeps it. Each result over `RESUME_DETAIL` goes whole to `details_path`, and the row keeps its start. The prompt of a row still over `ROW_MAX` is treated the same way."
    if (d := self.details_path) is None: return turn
    long, ref = _long_details(turn), f'{d.parent.name}/{d.name}'
    row = _clipped(turn, long, ref) if long else turn
    huge = len(json.dumps(row, ensure_ascii=False)) > ROW_MAX
    if not long and not huge: return turn
    rec = {'turn_id': turn.get('turn_id', ''), 'details': long} | ({'prompt': str(turn.get('prompt') or '')} if huge else {})
    try:
        d.parent.mkdir(parents=True, exist_ok=True)
        _append_line(d, json.dumps(rec, ensure_ascii=False) + '\n')
    except Exception: return turn
    return row | ({'prompt': _clip(turn.get('prompt'), RESUME_DETAIL), 'details': ref} if huge else {})

@patch
def _remember(self:Agent, prompt, text, error='', state='complete'):
    turn = {'at': time.time(), 'session': getattr(self, 'session_id', '') or '', 'state': state,
            'turn_id': self.current_turn_id, 'branch_id': self.current_branch_id,
            'model': self._be('turn').spec.name,
            'prompt': prompt_text(prompt), 'steered': list(self._steered), 'reply': text, 'error': error,
            'plan': dict(getattr(self, '_turn_plan', {})),
            'usage': self.turn_use.dict(), 'usage_label': repr(self.turn_use),
            'activity': self.activity.rows(mark=self.activity._mark)}
    self.history.append(turn)
    del self.history[:-HISTORY_TURNS]
    if (p := self.history_path) is not None:
        try:
            p.parent.mkdir(parents=True, exist_ok=True)
            self._last_span = _append_line(p, json.dumps(self._slim(turn), ensure_ascii=False) + '\n')
        except Exception: pass
    self._event('turn_end', turn_id=turn['turn_id'], state=state, error=error, usage=turn['usage'], reply=str(text or '')[:4000])
    for f in list(self.turn_ends):
        try: f(turn)
        except Exception: pass   # a listener never breaks the turn's record
    self._save_hist()
    if (d := getattr(self, 'runs_dir', None)) is not None: (d/PENDING).unlink(missing_ok=True)

