CHECKPOINT_BYTES = 2_000_000

@patch(as_prop=True)
def checkpoint_dir(self:Agent):
    "`<cfg>/checkpoints/<session>`, or None without a config dir."
    return None if self.cfg is None else self.cfg/'checkpoints'/self.session_id

@patch
def _checkpoint(self:Agent):
    "Save this turn's pre-write texts and created paths. While the checkpoint files total more than `CHECKPOINT_BYTES`, the oldest file is deleted. The newest file always stays. Returns '' or, when the files could not be written, a note saying so."
    d = self.checkpoint_dir
    if d is None or not self.before: return ''
    try:
        d.mkdir(parents=True, exist_ok=True)
        written = {p: self.host.text_at(p) or '' for p in self.new if p in self.before}
        (d/f'{self.current_turn_id}.json').write_text(json.dumps({'before': self.before, 'new': sorted(self.new), 'written': written, 'binary': sorted(self.binary)}))
    except OSError as e: return f'The file checkpoint for this turn was not saved ({agent_err(e)}), so /rewind cannot restore its files.'
    try:
        files = sorted(d.glob('*.json'), key=lambda p: p.stat().st_mtime)
        while len(files) > 1 and sum(p.stat().st_size for p in files) > CHECKPOINT_BYTES: files.pop(0).unlink()
    except OSError as e: return f'The file checkpoint was saved, but old checkpoints could not be removed ({agent_err(e)}).'
    return ''

def _snapshot(raw):
    "A file checkpoint as `(before, new, written, binary)`, from either on-disk shape."
    if isinstance(raw.get('before'), dict) and isinstance(raw.get('new'), list):
        return raw['before'], set(raw['new']), dict(raw.get('written') or {}), set(raw.get('binary') or ())
    return raw, set(), {}, set()

@patch
def _restore(self:Agent, turn_id, snap, delete, kept, binary):
    "Put checkpointed paths back: `delete` removed, `kept` and `binary` untouched, the rest written."
    restored, gone, bad = 0, 0, []
    for p, text in snap.items():
        if p in kept or p in binary: continue
        try:
            if p in delete: self.host.delete(p); gone += 1
            else:
                if text and Path(p).suffix == '.ipynb' and not text.startswith('{'): raise ValueError('the checkpoint holds the notebook as cell text, and writing it would replace the notebook with plain text')
                self.host.write(p, text); restored += 1
        except Exception as e: bad.append(f"could not {'remove' if p in delete else 'restore'} {p} ({agent_err(e)})")
    return (f'restored {restored} file(s) to before {turn_id}' + (f'; removed {gone} file(s) created that turn' if gone else '')
            + ''.join(f'; kept {p}: changed after the turn' for p in kept)
            + ''.join(f'; cannot restore {p} (binary)' for p in sorted(binary) if p in snap)
            + ''.join(f'; {b}' for b in bad))

@patch
def rewind(self:Agent, turn_id='', what='both'):
    "Put files, chat or both back to before `turn_id` (default the last), under one approval."
    turn_id = str(turn_id or (self.history[-1]['turn_id'] if self.history else self.current_turn_id))
    out, d = [], self.checkpoint_dir
    if what in ('files', 'both'):
        f, g = (d/f'{turn_id}.json', d/f'{turn_id}.git.json') if d is not None else (None, None)
        snap, new, written, binary = _snapshot(json.loads(f.read_text())) if f is not None and f.exists() else ({}, set(), {}, set())
        git = json.loads(g.read_text()) if g is not None and g.exists() else self.git_undo.get(turn_id, [])
        made = sorted(p for p in snap if p in new)
        delete = [p for p in made if (self.host.text_at(p) or '') == written.get(p)]
        kept = [p for p in made if p not in delete]
        undo = [t for t in git if t.get('undo')]
        if not snap and not git: out.append(f'no file checkpoint for {turn_id}')
        elif (blocked := self._git_blocked(undo, snap)): out.append(blocked)   # all or nothing: files without the git undo mismatch the tree
        elif self.approvals is not None and not self.approvals.request('rewind', {'paths': list(snap), 'delete': delete, 'kept': kept,
                                                                                  'git': [f"{t['tool']}: {t['summary']} (undoes {t['undoes']})" for t in undo]}, force=True).answer: out.append('rewind refused')
        else:   # git first; files are then written onto the tree they came from
            if git: out.append(self._undo_git(git))
            if snap: out.append(self._restore(turn_id, snap, set(delete), kept, binary))
    if what in ('chat', 'both'):
        try: out.append(f"chat on branch {self.undo_turn(turn_id)['branch_id']}, before {turn_id}")
        except Exception as e: out.append(agent_err(e))
    return '; '.join(out)


@patch
def _git_root(self:Agent, w):
    "The repository a kept git write happened in. A token kept without one uses the first root."
    return w.get('root') or str(self.host.roots[0])

@patch
def _git_blocked(self:Agent, writes, snap=()):
    "Why the turn's git writes cannot be undone now (HEAD, branch or other files moved in a repository they touched), or ''."
    left = 'git undo refused and files left as they are'
    from gheasy.repo import GitRepo
    def at(p):
        try: return Path(self.host.check(p)).resolve()
        except Exception: return (Path(self.host.roots[0]).resolve()/str(p).lstrip('/')).resolve()
    own = {at(p) for p in snap}
    for where in dict.fromkeys(self._git_root(w) for w in writes):
        last = next((w for w in reversed(writes) if w.get('head') and self._git_root(w) == where), None)
        if last is None: continue
        try: r = GitRepo.at(where); head = r.run('rev-parse', 'HEAD').strip()
        except Exception as e: return f'cannot read HEAD ({agent_err(e)}); {left} -- check the repository first, or /rewind chat'
        def ask(*a):
            try: return r.run(*a).rstrip()   # porcelain lines keep their leading status column
            except Exception: return ''
        if not head.startswith(last['head']): return f"HEAD moved after the turn ({last['head']}..{head[:9]}); {left} -- undo the later commits first, or /rewind chat"
        branch = ask('branch', '--show-current')
        if last.get('branch') and branch != last['branch']: return f"branch changed after the turn ({last['branch']} -> {branch or 'detached'}); {left} -- go back to {last['branch']} first, or /rewind chat"
        dirty = {(r.root/l[3:].split(' -> ')[-1]).resolve() for l in ask('status', '--porcelain', '--untracked-files=no').splitlines() if len(l) > 3}
        if (others := sorted(str(p.relative_to(r.root)) if p.is_relative_to(r.root) else str(p) for p in dirty - own)):
            return f"uncommitted changes to {', '.join(others)} after the turn; {left} -- commit or stash them first, or /rewind chat"
    return ''

@patch
def _undo_git(self:Agent, writes):
    "Apply a turn's git `undo` tokens newest first, each in its own repository, naming writes gheasy cannot undo."
    from gheasy.repo import GitRepo
    done, problems = 0, []
    for w in [w for w in reversed(writes) if w.get('undo')]:
        try: GitRepo.at(self._git_root(w)).undo(w['undo']); done += 1
        except Exception as e: problems.append(f"{w['tool']}: {agent_err(e)}")
    stuck = [w['tool'] for w in writes if not w.get('undo')]
    parts = [f'undid {done} git write(s)'] if done else []
    if stuck: parts.append(f'{len(stuck)} git write(s) this turn cannot be undone here: {", ".join(stuck)}')
    return '; '.join(parts + problems)

