@patch
def command(self:Agent, line):
    "Run a slash command. Returns text to show, or None when the command is unknown."
    line = (line or '').strip().lstrip('/')
    name, _, arg = line.partition(' ')
    arg = arg.strip()
    if name == 'model':
        if not arg: return (f'{self.routing.summary()}\n{"briefing":11} {self.profile} profile' + ('' if self.profile_choice != 'auto' else ' (auto)') +
                            (f'\n{"tools":11} {SHOWN_CHANNEL[tool_channel(s, session=self.turn_channel)]}' + ('' if self.turn_channel else ' (auto)') if (s := self.spec_or_none()) is not None else ''))
        job, _, m = arg.partition(' ')
        if job == 'tools':
            w = [x for x in m.split() if x != '--save']
            if len(w) != 1: return 'say /model tools native|text|auto, with --save to keep it in config.toml'
            try: return self.set_tool_channel(w[0], save='--save' in m.split())
            except (RuntimeError, ValueError, OSError) as e: return str(e)
        if not (words := [w for w in arg.split() if w != '--save']): return 'say /model [JOB] NAME --save to keep it in config.toml'
        pick, job = words[-1], words[0] if len(words) > 1 else 'turn'
        try: out = f'{model_note(self.set_model(pick, job))} · {self.profile} profile'
        except Exception as e: return agent_err(e)
        if '--save' not in arg.split(): return out
        try: return f'{out}\nsaved {config_set(f"jobs.{job}", pick)} in {config_path()}'
        except (ValueError, OSError) as e: return f'{out}\nnot saved: {e}'
    if name == 'sessions':
        every = self.sessions()
        rows = every if arg.lower() == 'all' else [s for s in every if self._from_here(s['id'])]
        if rows: return '\n'.join(f"{s['id']}  {s['turns']:>3} turns  {s['model']:<20} {s['title']}" for s in rows)
        if every: return 'no saved sessions from these folders; /sessions all lists every folder'
        where = str(self.history_path) if self.history_path is not None else '(history disabled: no cfg directory)'
        return f'no saved sessions in {where}; a session is saved after its first completed turn'
    if name == 'resume':
        try:
            s = self.resume_session(arg or 'latest')
            return f"resumed {s['id']} · {s['turns']} turns · {s['model']}"
        except Exception as e: return agent_err(e)
    if name == 'models': return models_table(self.model.name, legacy=arg.lower() in ('all', 'legacy'))
    if name == 'config': return self.config_command(arg)
    if name == 'subagents': return (d := self.subagents_command(arg))['error'] or d['note']
    if name == 'planmode':
        try: on = self.set_plan_mode(arg.lower() in ('on', 'yes', 'true', '1')) if arg else self.plan_mode
        except RuntimeError as e: return str(e)
        return 'plan mode on: tools that act are withheld, and the model proposes a plan' if on else 'plan mode off'
    if name == 'cost': return repr(self.use)
    if name == 'compact':
        t = self.compact(arg)
        return f'{self.compactor.note}\n\n{t}' if t else self.compactor.note
    if name == 'skills': return '\n'.join(f'{s.name:16} {s.source:8} {s.description[:90]}' for s in self.skills) or 'no skills found'
    if name == 'skill': return clip(_skill_text(self.skills, arg))
    if name == 'tools': return '\n'.join(sorted(getattr(t, '__name__', '?') for t in self.tools))
    if name == 'extensions': return '\n'.join(self.registry.notes) or 'no extensions loaded'
    if name == 'reload':
        self.reload()
        return f'reloaded: {len(self.tools)} tools, {len(self.skills)} skills'
    if name in ('plan', 'todos'):
        if not arg: return self.plan.md()
        if arg.lower() in ('clear', 'reset', 'none'): self.plan.clear(); self._save_plan(); return 'plan cleared'
        if '|' in arg:
            title, _, rest = arg.partition('|')
            items = [x.strip() for x in rest.split('|') if x.strip()]
        else:
            lines = [ln.strip() for ln in arg.splitlines() if ln.strip()]
            title, items = (lines[0], lines[1:]) if lines else (arg, [])
        self.plan.set(title, items); self._save_plan()
        return self.plan.md()
    if name == 'todo':
        if not arg: return self.plan.md()
        head, _, rest = arg.partition(' ')
        rest = rest.strip()
        if self.plan.find(head) is not None and rest:
            status, _, note = rest.partition(' ')
            if status in TODO_STATUSES:
                try: self.plan.update(head, status=status, note=note.strip() or None)
                except Exception as e: return agent_err(e)
                self._save_plan(); return self.plan.md()
        try: self.plan.add(arg)
        except Exception as e: return agent_err(e)
        self._save_plan(); return self.plan.md()
    if name == 'rewind':
        t, _, w = arg.partition(' ')
        if t in ('files', 'chat', 'both'): t, w = '', t
        return self.rewind(t, w.strip() or 'both')
    if name == 'branches':
        return '\n'.join(f"{'*' if b['branch_id'] == self.current_branch_id else ' '} {b['branch_id']:<16} from {b['parent_branch_id'] or '-'}@{b['parent_turn_id'] or '-'}" for b in self.branches())
    if name == 'branch':
        if not arg: return self.current_branch_id
        try: return f"on {self.switch_branch(arg)['branch_id']}"
        except Exception as e: return agent_err(e)
    if name == 'commit': return self.commit(*self._repo_arg(arg))
    if name == 'pr': return self.pull_request(*self._repo_arg(arg))
    if name in self.registry.commands:
        fn, _ = self.registry.commands[name]
        try: return fn(self, arg)
        except Exception as e: return agent_err(e)
    return None

