_agent_status, _agent_command = Agent.status, Agent.command

#: seconds a cancelled run gets to stop
Agent.cancel_grace = .25

def _stream_chunk(out, chunk):
    text = ''.join(out)
    if chunk == text: return ''
    return chunk[len(text):] if chunk.startswith(text) else chunk

class SessionBusy(RuntimeError):
    "A turn in a session another live process holds."

@patch
def _new_run(self:Agent, prompt):
    "A run for one turn. Raises `SessionBusy` before anything is written when another process holds this session."
    if not self.claim_session():
        raise SessionBusy(f"session {self.session_id} is in use by process {(self.session_owner(self.session_id) or {}).get('pid', '?')}")
    _run_store(self)
    with self._runs_lock:
        current = self.run()
        if current is not None and not current.terminal: raise RuntimeError('the assistant is already running')
        rid, d = f'run_{uuid.uuid4().hex[:12]}', self.runs_dir
        r = Run(rid, question=prompt_text(prompt), model=self.model.name, grace=self.cancel_grace, log=None if d is None else d/f'{rid}.log')
        r.key = self.inbox_key
        r.write(f'question: {r.question}')
        self._runs[r.id], self._foreground = r, r.id
        for old in list(self._runs)[:-100]: self._runs.pop(old, None)
        return r

@patch
def _release_run(self:Agent, run):
    "Drop a backend that a stop left running. The turn backend that replaces it starts with its conversation."
    if run.state not in ('detached', 'terminated'): return
    turn = (lambda s: (s.backend, s.model_id))(self.routing.spec('turn'))
    for key, backend in list(self._backends.items()):
        if backend is not run.backend: continue
        try: hist = _whole(backend.snapshot_hist()) if key == turn else None   # its worker may still be mid-call
        except Exception: hist = None
        self._backends.pop(key, None)
        if hist: self._be('turn').resume_hist(hist)

@dataclass
class TurnResult:
    "How one turn ended, for a host: its reply, its state, and the value it handed back."
    reply: str = ''
    state: str = ''           # 'complete', 'failed', 'cancelled', 'budget' or 'abandoned'
    error: str = ''
    usage: dict = field(default_factory=dict)
    result: object = None     # what `submit_result` received, validated against the `schema`
    session: str = ''
    turn_id: str = ''

class TurnFailed(Exception):
    "A strict `ask` whose turn did not complete. `result` is its `TurnResult`."
    def __init__(self, result, why=''):
        super().__init__(why or f'the turn ended {result.state}: {result.error or result.reply}')
        self.result = result

class ResultMissing(TurnFailed):
    "A strict `ask` with a `schema` whose model never handed back a valid result."

RESULT_ASK = '\n\nWhen you have the answer, call `submit_result` once with it, then reply in one sentence.'
RESULT_AGAIN = 'You have not called `submit_result`. Call it now with the result, matching the schema in its description.'

def _result_tool(schema, got):
    "A `submit_result` tool that validates its payload against `schema` and keeps the first valid one in `got['value']`."
    if isinstance(schema, dict):
        import jsonschema
        spec = schema
        def check(v): jsonschema.validate(v, schema); return v
    else:
        from pydantic import TypeAdapter
        ta = TypeAdapter(schema)
        spec, check = ta.json_schema(), ta.validate_python
    def submit_result(
        result:dict|list|str|int|float|bool, # the result, matching the schema in this tool's description
    ):
        try: got.setdefault('value', check(result))
        except Exception as e: return f'that result does not match the schema ({agent_err(e)}); call submit_result again with it fixed'
        return 'result received'
    submit_result.__doc__ = f'Hand back the result of this task, once, as `result`. Its JSON schema:\n{json.dumps(spec)}'
    return small_tool(submit_result)   # the small profile keeps only marked registry tools

def _with_note(prompt, note):
    "`prompt` with `note` after its text. A prompt of parts gets the note on its last text part."
    if isinstance(prompt, str): return prompt + note
    parts = list(prompt)
    if parts and isinstance(parts[-1], str): parts[-1] += note
    else: parts.append(note.strip())
    return parts

@patch
def _turn_result(self:Agent, out, got):
    "The `TurnResult` of the turn that just ended, from the row it left."
    row = self.history[-1] if self.history and self.history[-1].get('turn_id') == self.current_turn_id else {}
    state = row.get('state') or ('complete' if isinstance(out, str) else 'cancelled')
    return TurnResult(reply=str(row.get('reply') or (out if isinstance(out, str) else '')), state=state,
                      error=str(row.get('error') or ''), usage=dict(row.get('usage') or {}), result=got.get('value'),
                      session=self.session_id, turn_id=self.current_turn_id)

@patch
def ask(self:Agent, prompt,
        schema=None,   # a type pydantic validates, or a JSON schema dict: the model hands back a value of it through `submit_result`
        result=False,  # return a `TurnResult` rather than the reply text
        strict=False,  # raise `TurnFailed` for a turn that did not complete, and `ResultMissing` for a `schema` never filled
        **kw):
    "One registered turn. A stopped turn is recorded and not replayed. Without `schema`, `result` or `strict`, it returns the reply text, a dict when the turn was stopped, or a failure note."
    if schema is None and not result and not strict: return self._ask_once(prompt, **kw)
    if (r := self.run()) is not None and not r.terminal: raise RuntimeError('the assistant is already running')   # before the running turn is handed a tool
    got, tool = {}, None
    if schema is not None:
        tool = _result_tool(schema, got)
        self.add_tool(tool)
    try:
        out = self._ask_once(_with_note(prompt, RESULT_ASK) if tool else prompt, **kw)
        if tool is not None and 'value' not in got and self._turn_result(out, got).state == 'complete':
            out = self._ask_once(RESULT_AGAIN, **kw)   # once: a model that ignores it twice is told no more
    finally:
        if tool is not None:
            try: self.registry.tools.remove(tool); self.refresh()
            except Exception: pass   # never in place of what the turn raised
    tr = self._turn_result(out, got)
    if strict and tr.state != 'complete': raise TurnFailed(tr)
    if strict and tool is not None and 'value' not in got: raise ResultMissing(tr, 'the model never handed back a valid result')
    return tr

def _budget_callback(agent):
    "A chat callback that passes `agent` what the turn has spent after each model step. A budget can then stop the turn."
    from urai.core import ChatCallback
    class BudgetCallback(ChatCallback):
        order = 15   # after urai's `UsageCallback` folds the step into `chat.use`
        def after_response(self): agent._spend(self.chat.use)
    return BudgetCallback

@patch
def _spend(self:Agent, use):
    "Stop the turn once it, or the session with it, is past a budget. The reason waits for the row of the turn."
    tok, cost = getattr(use, 'total_tokens', 0) or 0, getattr(use, 'cost', 0.) or 0.
    for limit, spent, what in ((self.max_tokens, tok, 'tokens this turn'), (self.max_cost, cost, 'dollars this turn'),
                               (self.session_max_tokens, self.use.total + tok, 'tokens this session'),
                               (self.session_max_cost, self.use.cost + cost, 'dollars this session')):
        if limit is not None and spent > limit:
            self._budget_hit = f'stopped by its budget: {spent:,.4g} {what}, past {limit:,.4g}'
            if (run := current_run()) is not None: run.request_cancel()
            return

@patch
def queue(self:Agent, prompt):
    "Hold `prompt` for a turn after this one. `run_queued` runs what is held, in order. Returns how many prompts wait."
    self.queued.append(prompt)
    return len(self.queued)

@patch
def run_queued(self:Agent, **kw):
    "Run every queued prompt in order, each its own turn, and return their `TurnResult`s."
    out = []
    while True:
        try: p = self.queued.popleft()
        except IndexError: return out
        out.append(self.ask(p, result=True, **kw))

UNREAD = 'Sent during the last turn, after its last tool call, so not yet read:'

@patch
def _with_unread(self:Agent, prompt):
    "`prompt` preceded by the steering the last turn never read. A line sent too late is not lost. A running turn keeps its own."
    if (r := self.run()) is None or not r.terminal or not (msgs := r.drain_inbox()): return prompt
    head = UNREAD + '\n' + '\n'.join(msgs)
    return f'{head}\n\n{prompt}' if isinstance(prompt, str) else [head, *prompt]

@patch
def _ask_once(self:Agent, prompt, **kw):
    "One registered turn. A stopped turn is recorded, and not replayed."
    prompt = self._with_unread(prompt)
    run, kept = self._new_run(prompt), [False]
    def keep(state, text='', error=''):
        "Write the row once, however the turn ended. A stop that a budget made is recorded as `budget`."
        if kept[0]: return
        if state == 'cancelled' and getattr(self, '_budget_hit', ''): state, error = 'budget', self._budget_hit
        self._remember(prompt, text, error, state=state)
        kept[0] = True
    try:
        self._begin_turn(run)
        if self.start() is None:
            run.finish('failed'); keep('failed', self.note, self.note); return self.note
        backend = self._be('turn')
        if not run.start(backend): keep('cancelled'); return run.dict()
        with run_context(run):
            outgoing = self._prepare(prompt)
            text = backend.send(outgoing, run=run, **kw)
        if run.cancelled:
            run.finish(); keep('cancelled'); return run.dict()
        outcome = 'failed' if getattr(backend, 'turn_error', '') else 'completed'
        out = self._finish(text, prompt)
        run.finish(outcome)
        kept[0] = True
        return out
    except Exception as e:
        if run.cancelled:
            run.finish(); keep('cancelled'); return run.dict()
        run.finish('failed')
        self.note = f'the assistant failed ({agent_err(e)})'
        keep('failed', self.note, agent_err(e))
        return self.note
    finally:
        if not run.terminal: run.finish('cancelled')
        keep('abandoned')

@patch
def stream(self:Agent, prompt, on_registered=None, **kw):
    "One registered turn as markdown chunks. A stopped turn is recorded and not replayed."
    prompt = self._with_unread(prompt)
    run, out, kept = self._new_run(prompt), [], [False]
    def keep(state, text='', error=''):
        "Write the row once, however the turn ended. A stop that a budget made is recorded as `budget`."
        if kept[0]: return
        if state == 'cancelled' and getattr(self, '_budget_hit', ''): state, error = 'budget', self._budget_hit
        self._remember(prompt, text, error, state=state)
        kept[0] = True
    try:
        self._begin_turn(run)                  
        if self.start() is None:
            run.finish('failed')
            keep('failed', self.note, self.note)
            yield self.note; return
        backend = self._be('turn')
        if not run.start(backend): keep('cancelled'); return
        if on_registered is not None: on_registered(run)
        if run.cancelled: run.finish(); keep('cancelled'); return
        with run_context(run):
            outgoing = self._prepare(prompt)
            for chunk in backend.stream(outgoing, run=run, **kw):
                if run.cancelled: break
                chunk = _stream_chunk(out, chunk)
                if chunk: out.append(chunk); run.hear(chunk); yield chunk
        outcome = 'failed' if getattr(backend, 'turn_error', '') else 'completed'
        if run.cancelled: run.finish(); keep('cancelled', ''.join(out))
        else:
            tail = self._finish(''.join(out), prompt)[len(''.join(out)):]
            run.finish(outcome)
            kept[0] = True
            if tail: yield tail
    except Exception as e:
        if run.cancelled: run.finish(); keep('cancelled', ''.join(out)); return
        run.finish('failed')
        self.note = f'the assistant failed ({agent_err(e)})'
        keep('failed', self.note, agent_err(e))
        yield f'\n\n{self.note}'
    finally:
        if not run.terminal: run.finish('cancelled')
        keep('abandoned', ''.join(out))

@patch
def cancel(self:Agent, run_id='', grace=None):
    "Cancel one run, or the foreground root, and return its structured terminal state."
    run = self.run(run_id)
    if run is None:return {'id': run_id or None, 'state': 'idle', 'children': []}
    if self.approvals is not None:self.approvals.cancel_all('the run was cancelled', run=run)
    run.cancel(self.cancel_grace if grace is None else grace)
    self._release_run(run)
    return run.dict()

@patch
def terminate(self:Agent, run_id=''):
    "Terminate one run without waiting for the provider."
    run = self.run(run_id)
    if run is None:return {'id': run_id or None, 'state': 'idle', 'children': []}
    run.terminate(); self._release_run(run)
    return run.dict()

@patch
def status(self:Agent):
    out = _agent_status(self)
    out['runs'] = self.runs(active=True)
    out['busy'] = bool(out['runs'])
    return out

@patch
def command(self:Agent, line):
    raw = (line or '').strip().lstrip('/')
    name, _, arg = raw.partition(' ')
    if name == 'stop': return json.dumps(self.cancel(arg.strip()), ensure_ascii=False)
    if name == 'runs': return json.dumps(self.runs(active=arg.strip() != 'all'), ensure_ascii=False)
    if name == 'tell': return self.tell(*arg.partition(' ')[::2])
    if name == 'watch': return self.watch(arg.strip())
    if name == 'unwatch': return self.unwatch(arg.strip() or 'all')
    if name == 'learned':
        if self.cfg is None: return 'no config folder, so no learned folder'
        out = learned_command(learned_folder(self.cfg), arg)
        if arg.strip() in ('on', 'off'): self.refresh()
        return out
    return _agent_command(self, line)


