@patch(as_prop=True)
def runs_dir(self:Agent):
    "`<cfg>/runs/<session>`: one transcript per run plus `monitors.log`, or None without a config dir."
    return None if self.cfg is None else self.cfg/'runs'/self.session_id

@patch
def tell(self:Agent, run_id, text=''):
    "Queue `text` for the sub-agent working `run_id`. The sub-agent reads it after its next tool call or reply."
    if (r := self.run(run_id)) is None: return f'no run named {run_id!r}'
    if r.terminal: return f'{run_id} finished ({r.state}); nothing is listening'
    if not text.strip(): return 'nothing to say'
    r.tell(text)
    return f'told {run_id}'

@patch
def steer(self:Agent, text):
    "Send `text` to the running root turn, with its next tool result. Returns '' when no turn is listening."
    r = self.run()
    if r is None or r.terminal or r.cancelled or not text.strip(): return ''
    r.tell(text)
    return f'told {r.id}'

@patch
def leftovers(self:Agent):
    "What the root turn was sent and never read, taken once."
    return [] if (r := self.run()) is None else r.drain_inbox()

@patch
def watch(self:Agent, target=''):
    "Open a pane following a run's transcript or `monitors`. With no target, list what can be watched."
    if not target:
        rows = [f"{r['id']}  {r['state']:10} {r['question'][:50]}  {r.get('log') or ''}"
                for r in self.runs(active=True) + [r.dict() for r in self._monitor_runs() if not r.terminal]]
        self.monitors.sync()
        rows += [f'{w.id}  watching   {w.folder}  {w.reviews} review(s)' for w in self.monitors.all()]
        return '\n'.join(rows) or 'nothing is running or watched'
    log = self.monitors.log if target == 'monitors' else getattr(self.run(target), 'log', None)
    if log is None: return f'nothing to watch for {target!r}'
    log.parent.mkdir(parents=True, exist_ok=True); log.touch()
    self.registry.fire('watch', self, target, log)
    if self.on_watch is not None:
        self.on_watch(target, log)
        return f'watching {target}'
    if target in self._panes: return f'already watching {target} in pane {self._panes[target]}'
    cmd = follow_cmd(log, log.parent/'now.json')   # the CLI writes its snapshot, and so its palette, beside the transcripts
    try: self._panes[target] = self.host.open_pane(cmd, title=target)
    except Exception: return f'no tmux here; in another terminal run: {cmd}'
    if (r := self.run(target)) is not None and r.terminal: self._pane_done[target] = float('inf')   # asked for after the run ended: it stays until `/unwatch`
    return f'watching {target} in pane {self._panes[target]}'

@patch
def reap_panes(self:Agent, now=None):
    "Close the `/watch` pane of each run that ended, or left the list, `PANE_LINGER` seconds ago. Nothing closes when `pane_close_done` is false. The `monitors` pane and panes this agent did not open stay."
    if not setting('pane_close_done', True): return []
    now, closed = time.monotonic() if now is None else now, []
    for k in list(self._panes):
        if k == 'monitors': continue
        if (r := self.run(k)) is not None and not r.terminal: self._pane_done.pop(k, None); continue
        if now - self._pane_done.setdefault(k, now) >= PANE_LINGER and self.unwatch(k).startswith('closed'): closed.append(k)
    return closed

_AT_FILE = re.compile(r'(?<!\S)@(\S+)')
_SUBST = re.compile(r'\$(\d+)|\$ARGUMENTS')
SUBTASK = 'Delegate this to a sub-agent with `delegate_async` rather than doing it yourself:'

@patch
def _command_file(self:Agent, name):
    "The command's markdown file: a root's `.agents/commands/` if opted in, then `<cfg>/commands/`."
    if not name or name in ('.', '..') or Path(name).name != name: return None
    dirs = [Path(r)/'.agents'/'commands' for r in (self.host.roots if self.project_extensions else ())]
    if self.cfg: dirs.append(self.cfg/'commands')
    return first(f for d in dirs if (f := d/f'{name}.md').is_file())

@patch
def _fill_command(self:Agent, body, arg):
    "Fill `$ARGUMENTS` and `$1..$n` in one pass, then inline each readable `@path` as a file."
    try: words = shlex.split(arg)
    except ValueError: words = arg.split()
    def word(m):
        if m.group(1) is None: return arg
        return words[int(m.group(1)) - 1] if 0 < int(m.group(1)) <= len(words) else m.group(0)
    body = _SUBST.sub(word, body)
    def inline(m):
        path = m.group(1).rstrip('?!,;:.)]}\'"')
        try: text = self.host.read(str(self.host.check(path)))
        except Exception: text = None
        return m.group(0) if text is None else f'<file path="{path}">\n{clip(text, MAX_CONTEXT_FILE).rstrip()}\n</file>'
    return _AT_FILE.sub(inline, body)

@patch
def expand_command(self:Agent, line):
    "The prompt a `/name ARGS` line stands for, from a skill or a command file, else None."
    name, _, arg = line.strip()[1:].partition(' ')
    if name.lower() in {s.name.lower() for s in self.skills}: return line.strip()
    if (f := self._command_file(name)) is None: return None
    text = f.read_text()
    try: meta, body = frontmatter(text)
    except Exception: meta, body = {}, text.split('\n---\n', 1)[-1]
    body = self._fill_command(body, arg.strip()).strip()
    return f'{SUBTASK}\n\n{body}' if meta.get('subtask') else body

@patch
def unwatch(self:Agent, target='all'):
    "Close the pane on `target`, or every pane."
    closed = []
    for k in (list(self._panes) if target == 'all' else [target]):
        if k not in self._panes: continue
        self._pane_done.pop(k, None)
        try: self.host.close_pane(self._panes.pop(k)); closed.append(k)
        except Exception: pass
    return f"closed {', '.join(closed)}" if closed else 'nothing was being watched'


