_HISTORY_LOCKS, _HISTORY_LOCKS_LOCK = {}, threading.RLock()
_SESSION_META_VERSION = 3
LEGACY_GAP = 1800
_SESSION_DEFAULTS = {'title': '', 'title_turns': 0, 'muted': False, 'manual': False, 'roots': ()}

_HARNESS = re.compile(r'<(system-reminder|notebook|background-results|watch-results|sent_mid_turn)\b[^>]*>.*?</\1>', re.S)

def request_body(prompt):
    "`request_text` without the harness's blocks, or a `<user-request>` tag a prompt cut short kept."
    return _HARNESS.sub(' ', re.sub(r'</?user-request>', ' ', request_text(prompt))).strip()

def _cut_title(text, n):
    "`text` in at most `n` characters, cut at a word with an ellipsis."
    return text if len(text) <= n else text[:n - 1].rsplit(' ', 1)[0].rstrip(',;:') + '…'

def request_title(prompt, n=80):
    "A session's title from its first request: the first sentence of `request_body`, in at most `n` characters."
    text = ' '.join(request_body(prompt).split()).lstrip('▌│┆┃ ')
    if (m := re.match(r'(.+?[.?!])(\s|$)', text)): text = m.group(1)
    return _cut_title(text, n)

_TITLE_LABEL = re.compile(r'^(?:conversation\s+)?title\s*:\s*', re.I)

def model_title(text, n=80):
    "A title the summary model wrote, without `**bold**`, a `Title:` label, quotes or what follows a spaced `---` rule, in at most `n` characters."
    text = re.sub(r'\*\*(.+?)\*\*', r'\1', ' '.join(str(text or '').split()))
    text = re.split(r'\s-{3,}(?:\s|$)', text + ' ')[0]
    return _cut_title(_TITLE_LABEL.sub('', text.strip().lstrip('# ')).strip('"\'“” '), n)

def _history_lock(agent):
    "One lock per history file. Agents sharing a log serialise their writes with it."
    path = agent.history_path
    if path is None: return agent.__dict__.setdefault('_own_history_lock', threading.RLock())
    key = str(path.resolve())
    with _HISTORY_LOCKS_LOCK: return _HISTORY_LOCKS.setdefault(key, threading.RLock())

@patch(as_prop=True)
def sessions_path(self:Agent):
    "`<cfg>/<history_name>-sessions.json`, the session index, or None without a config dir."
    return None if self.cfg is None else self.cfg/f'{self.history_name}-sessions.json'

def _session_rows(agent):
    path = agent.sessions_path
    if path is None or not path.exists(): return {}
    try:
        data = json.loads(path.read_text())
        if not isinstance(data, dict): raise ValueError('the document is not an object')
        rows = data.get('sessions', {})
        if not isinstance(rows, dict): raise ValueError('sessions is not an object')
        agent.history_problem = ''
        return rows
    except Exception as e:
        agent.history_problem = f'session metadata is malformed ({agent_err(e)})'
        return None

def _write_session_rows(agent, rows):
    path = agent.sessions_path
    if path is None:return
    with atomic_save(path, 'w') as f:
        f.write(json.dumps({'version': _SESSION_META_VERSION, 'sessions': rows}, ensure_ascii=False, indent=2) + '\n')

_BRANCH_META_VERSION = 1
BRANCH_POLICIES = ('keep', 'discard', 'auto')

@patch(as_prop=True)
def branches_path(self:Agent):
    "`<cfg>/<history_name>-branches.json`, the branch records, or None without a config dir."
    return None if self.cfg is None else self.cfg/f'{self.history_name}-branches.json'

def _branch_rows(agent):
    "Every recorded branch, or None when the file is there but unreadable."
    path = agent.branches_path
    if path is None or not path.exists(): return {}
    try:
        data = json.loads(path.read_text())
        if not isinstance(data, dict): raise ValueError('the document is not an object')
        rows = data.get('branches', {})
        if not isinstance(rows, dict): raise ValueError('branches is not an object')
        return rows
    except Exception as e:
        agent.history_problem = f'branch metadata is malformed ({agent_err(e)})'
        return None

def _write_branch_rows(agent, rows):
    path = agent.branches_path
    if path is None:return
    with atomic_save(path, 'w') as f:
        f.write(json.dumps({'version': _BRANCH_META_VERSION, 'branches': rows}, ensure_ascii=False, indent=2) + '\n')

@patch
def branch_meta(self:Agent, branch_id=''):
    "One branch's parentage, revision and context manifest. `main` is the conversation as recorded."
    branch_id = str(branch_id or self.current_branch_id)
    with _history_lock(self):
        rows = _branch_rows(self)
        row = {} if rows is None else dict(rows.get(branch_id, {}))
    return {'version': _BRANCH_META_VERSION, 'branch_id': branch_id, 'revision': 0,
            'parent_branch_id': '', 'parent_turn_id': '', 'parent_part_id': '', 'stage': '',
            'created': 0.0, 'shaped': False, 'manifest': {}, 'rewrites': {}} | row

@patch
def branches(self:Agent):
    "Every branch this history knows, newest first, with `main` always present."
    with _history_lock(self): rows = _branch_rows(self) or {}
    out = [self.branch_meta(bid) for bid in rows]
    if 'main' not in rows: out.append(self.branch_meta('main'))
    return sorted(out, key=lambda row: row['created'], reverse=True)

@patch
def save_branch(self:Agent, branch_id, revision=None, **changes):
    "Record one branch. A stale `revision` raises `BranchChanged` and writes nothing."
    branch_id = str(branch_id)
    bad = [k for k in changes.get('manifest', {}).values() if k not in BRANCH_POLICIES]
    if bad: raise ValueError(f'unknown context policy {bad[0]!r}')
    with _history_lock(self):
        rows = _branch_rows(self)
        if rows is None: raise ValueError(self.history_problem)
        held = dict(rows.get(branch_id, {}))
        if revision is not None and int(held.get('revision', 0)) != int(revision):
            raise BranchChanged(f'branch {branch_id} moved to revision {held.get("revision", 0)}')
        row = (self.branch_meta(branch_id) | held | dict(changes) |
               {'branch_id': branch_id, 'revision': int(held.get('revision', 0)) + 1})
        row.setdefault('created', time.time())
        if not row['created']: row['created'] = time.time()
        row['shaped'] = (any(p != 'auto' for p in (row.get('manifest') or {}).values())
                         or bool(row.get('rewrites')))
        rows[branch_id] = row
        _write_branch_rows(self, rows)
        return dict(row)

def _index_turn(agent, turn, start, end):
    "Fold one appended turn into the index. The caller holds `_history_lock`."
    sid = turn.get('session') or ''
    if not sid: return
    rows = _session_rows(agent)
    if rows is None: return
    # a line that does not follow the indexed end: another writer or an untagged turn came between
    if _index_start(agent, rows) != start: return agent.rebuild_index()
    row = dict(rows.get(sid) or {})
    row['turns'] = int(row.get('turns', 0)) + 1
    row['last_at'], row['last_offset'] = turn.get('at', 0), end
    row['model'] = turn.get('model', '')
    if (fresh := row.get('first_offset') is None):
        row['first_offset'], row['first_at'] = start, turn.get('at', 0)
        row['first_title'] = request_title(turn.get('prompt', ''))
    _set_spans(row, _add_span(row.get('spans') or [], start, end) if fresh or 'spans' in row else None)
    rows[sid] = {'version': _SESSION_META_VERSION, **_SESSION_DEFAULTS} | row
    _write_session_rows(agent, rows)

_INDEX_KEYS = ('turns', 'first_at', 'first_offset', 'first_title', 'last_at', 'last_offset', 'model', 'spans')
MAX_SPANS = 256   #: byte ranges an index row lists; past this a session is read from its first turn to its last

def _add_span(spans, start, end):
    "`spans` with `[start, end]` added. The range joins the last one when they touch. Returns None past `MAX_SPANS` or without `spans`."
    if spans is None: return None
    out = [list(s) for s in spans]
    if out and out[-1][1] == start: out[-1][1] = end
    else: out.append([start, end])
    return out if len(out) <= MAX_SPANS else None

def _join_spans(a, b):
    "The ranges of `a` then `b`, or None when either is missing or the sum is too many."
    if a is None or b is None: return None
    for s, e in b:
        if (a := _add_span(a, s, e)) is None: return None
    return a

def _set_spans(row, spans):
    if spans is None: row.pop('spans', None)
    else: row['spans'] = spans

def _index_start(agent, rows):
    "Where the log has to be read from: None when the index covers it, 0 to rebuild, else where the index ends."
    # a title set before any turn names no bytes, so only rows with turns say what is indexed
    logged = [r for r in rows.values() if r.get('turns')]
    if not logged or any(int(r.get('version', 0)) < _SESSION_META_VERSION or 'last_offset' not in r for r in logged): return 0
    end, size = max(int(r['last_offset']) for r in logged), agent.history_path.stat().st_size
    if size == end: return None
    # smaller than a recorded offset: rotated or replaced
    return 0 if size < end else end

def _legacy_seed(rows):
    "The newest `legacy-N` and when it ended, so a catch-up numbers untagged turns as a full read would."
    n = max((int(s[7:]) for s in rows if s.startswith('legacy-') and s[7:].isdigit()), default=0)
    return n, (float(rows[f'legacy-{n}'].get('last_at') or 0) if n else None)

def _index_from_log(p, offset=0, legacy_n=0, legacy_last=None):
    "Stream the log from `offset` a line at a time and describe every conversation in it, with its byte range."
    found = {}
    with p.open('rb') as f:
        f.seek(offset)
        for raw in f:
            if not raw.endswith(b'\n'): break  # still being written: the next catch-up reads it
            start, offset = offset, offset + len(raw)
            line = raw.decode('utf-8', 'replace').strip()
            if not line: continue
            try: turn = json.loads(line)
            except Exception: continue
            sid, at = turn.get('session') or '', float(turn.get('at') or 0)
            if not sid:
                if legacy_last is None or at - legacy_last > LEGACY_GAP: legacy_n += 1
                sid, legacy_last = f'legacy-{legacy_n}', at
            if sid not in found:
                found[sid] = {'turns': 0, 'first_at': at, 'first_offset': start, 'first_title': request_title(turn.get('prompt', '')), 'spans': []}
            row = found[sid]
            row['turns'] += 1
            row['last_at'], row['last_offset'] = at, offset
            _set_spans(row, _add_span(row.get('spans'), start, offset))
            row['model'] = turn.get('model', '')
    return found

def _index_from_history(agent):
    "The same index for in-memory turns, without offsets."
    found, legacy_n, legacy_last = {}, 0, None
    for turn in agent.history:
        sid, at = turn.get('session') or '', float(turn.get('at') or 0)
        if not sid:
            if legacy_last is None or at - legacy_last > LEGACY_GAP: legacy_n += 1
            sid, legacy_last = f'legacy-{legacy_n}', at
        if sid not in found: found[sid] = {'turns': 0, 'first_at': at, 'first_title': request_title(turn.get('prompt', ''))}
        row = found[sid]
        row['turns'] += 1
        row['last_at'], row['model'] = at, turn.get('model', '')
    return found

@patch
def rebuild_index(self:Agent, force=False):
    "Index the log's conversations with byte ranges, or in-memory turns without a log."
    with _history_lock(self):
        rows = _session_rows(self)
        if rows is None: return {}
        p = self.history_path
        logged = p is not None and p.exists()
        start = _index_start(self, rows) if logged and not force else 0
        if start is None: return rows
        if start and not (found := _index_from_log(p, start, *_legacy_seed(rows))): return rows
        if not start: found = _index_from_log(p) if logged else _index_from_history(self)
        for sid, row in found.items():
            if start and (old := rows.get(sid) or {}).get('turns'):
                found[sid] = old | row | {k: old[k] for k in ('first_at', 'first_offset', 'first_title') if k in old} | {'turns': int(old['turns']) + row['turns']}
                _set_spans(found[sid], _join_spans(old.get('spans'), row.get('spans')))
        out = {sid: {'version': _SESSION_META_VERSION, **_SESSION_DEFAULTS}
                    | {k: v for k, v in (rows.get(sid) or {}).items() if k in _SESSION_DEFAULTS}
                    | row
               for sid, row in found.items()}
        for sid, row in rows.items():
            if sid in out: continue
            # a full read that did not find it: its offsets name bytes that are gone, its title is still the person's
            out[sid] = {k: v for k, v in row.items() if start or not logged or k not in _INDEX_KEYS} | {'version': _SESSION_META_VERSION}
        if logged: _write_session_rows(self, out)
        return out

def _session_turns(agent, sid): return agent.session_turns(sid)

@patch
def session_meta(self:Agent, sid=None):
    "A session's stored metadata: title, whether it is muted, and the folders it ran in."
    sid = sid or self.session_id
    with _history_lock(self):
        rows = _session_rows(self)
        row = {} if rows is None else dict(rows.get(sid, {}))
    return {'version': _SESSION_META_VERSION, **_SESSION_DEFAULTS} | row

def _set_session_meta(agent, sid, **changes):
    with _history_lock(agent):
        rows = _session_rows(agent)
        if rows is None: raise ValueError(agent.history_problem)
        row = {'version': _SESSION_META_VERSION, **_SESSION_DEFAULTS} | dict(rows.get(sid, {})) | changes
        rows[sid] = row
        _write_session_rows(agent, rows)
        return dict(row)

