@patch
def summarize_session(self:Agent, sid=None, force=False):
    "Title a session with the summary model, again each time its turn count doubles, unless the title was set by hand."
    sid = sid or self.session_id
    turns, meta = _session_turns(self, sid), self.session_meta(sid)
    if not turns or (meta['manual'] and not force): return meta
    n = len(turns)
    if not force and meta['title_turns'] and n < meta['title_turns'] * 2:return meta
    fallback = meta['title'] or request_title(turns[0].get('prompt', ''))
    prompt = '\n'.join(turn_prompt(t) for t in turns[-8:])
    try:
        title = model_title(self.oneshot(prompt, 'Write a short conversation title. Output only the title.', 'summary', 32))
        if not title: raise ValueError('the summary model returned no title')
        self.history_problem = ''
    except Exception as e:
        self.history_problem = f'title summary failed ({agent_err(e)})'
        return _set_session_meta(self, sid, title=meta['title'] or fallback)
    return _set_session_meta(self, sid, title=title, title_turns=n, manual=False)

if '_agent_load_history' not in globals():
    _agent_load_history, _agent_remember = Agent._load_history, Agent._remember
    _agent_sessions, _agent_session_turns = Agent.sessions, Agent.session_turns

@patch
def _load_history(self:Agent):
    self.history_problem = ''
    with _history_lock(self): return _agent_load_history(self)

@patch
def refresh_history(self:Agent):
    "Reload the history log and the session and branch records, and return the sessions."
    with _history_lock(self):
        _agent_load_history(self)
        _session_rows(self); _branch_rows(self)
    return self.sessions()

@patch
def session_count(self:Agent):
    "How many turns the whole log holds, from the index rather than from a parse of it."
    return sum(int(r.get('turns', 0)) for r in self.rebuild_index().values())

@patch
def recover_turns(self:Agent):
    "Write an `interrupted` row, with its prompt, for each turn whose process died before its row. Returns how many were written."
    if self.cfg is None or (p := self.history_path) is None: return 0
    n = 0
    for f in sorted((self.cfg/'runs').glob(f'*/{PENDING}*')):
        by = f.name[len(PENDING) + 1:]      # `turn.json.<pid>`: a recoverer took it, and may have died doing so
        if by and (not by.isdigit() or _alive(by)): continue
        if _alive((_read_json(f) or {}).get('pid')): continue   # still running, in this process or another
        mine = f.with_name(f'{PENDING}.{os.getpid()}')
        try: f.rename(mine)                 # one process recovers it, however many list sessions at once
        except OSError: continue
        t = _read_json(mine) or {}          # read again: a live turn may have taken its place before the rename
        if _alive(t.get('pid')):
            try: mine.rename(f.parent/PENDING)
            except OSError: pass
            continue
        if t.get('turn_id') and any(r.get('turn_id') == t['turn_id'] for r in self.session_turns(f.parent.name)):
            mine.unlink(missing_ok=True)    # its row was written; only the file was left behind
            continue
        row = {'at': t.get('at') or mine.stat().st_mtime, 'session': f.parent.name, 'state': 'interrupted',
               'turn_id': t.get('turn_id', ''), 'branch_id': 'main', 'model': t.get('model', ''),
               'prompt': str(t.get('prompt', '')), 'steered': [], 'reply': '',
               'error': 'the process ended during this turn', 'activity': []}
        with _history_lock(self):
            p.parent.mkdir(parents=True, exist_ok=True)
            _append_line(p, json.dumps(row, ensure_ascii=False) + '\n')
        mine.unlink(missing_ok=True)
        n += 1
    return n

@patch
def sessions(self:Agent):
    "Conversations from the index, newest first, titled by the user or the first prompt. A turn whose process died is recovered first."
    self.recover_turns()
    rows = self.rebuild_index()
    if not rows: return _agent_sessions(self)
    return sorted([{'id': sid, 'turns': int(r.get('turns', 0)), 'at': r.get('last_at', 0),
                    'first_at': r.get('first_at', 0), 'model': r.get('model', ''),
                    'title': (r.get('title') if r.get('manual') else model_title(r.get('title'))) or r.get('first_title', ''),
                    'title_turns': r.get('title_turns', 0), 'muted': bool(r.get('muted', False)),
                    'roots': list(r.get('roots') or ())}
                   for sid, r in rows.items() if r.get('turns')],
                  key=lambda row: row['at'], reverse=True)

@patch
def session_turns(self:Agent, sid):
    "One conversation's turns, read from its indexed byte ranges and filtered by session, with long tool results from its details file."
    sid = str(sid)
    row, p = self.rebuild_index().get(sid), self.history_path
    if row is None or 'first_offset' not in row or p is None or not p.exists():
        return _agent_session_turns(self, sid)
    spans, chunks = row.get('spans') or [(row['first_offset'], row.get('last_offset', 0))], []
    with _history_lock(self):
        with p.open('rb') as f:
            for s, e in spans:
                f.seek(int(s)); chunks.append(f.read(max(0, int(e) - int(s))))
    mine = (lambda t: not (t.get('session') or '')) if sid.startswith('legacy-') else (lambda t: (t.get('session') or '') == sid)
    return hydrate_turns(self.cfg, [t for t in map(_log_turn, b'\n'.join(chunks).split(b'\n')) if t is not None and mine(t)])

@patch
def _remember(self:Agent, prompt, text, error='', state='complete'):
    with _history_lock(self):
        _agent_remember(self, prompt, text, error, state)
        if (span := self.__dict__.pop('_last_span', None)) and self.history: _index_turn(self, self.history[-1], *span)
        if self.history_path is not None and self.history_path.exists():   # a session gets its title once, and every folder it runs in
            meta, sid = self.session_meta(), self.session_id
            saved = list(meta.get('roots') or ())
            roots = saved + [r for r in map(str, self.host.roots) if r not in saved]
            fill = ({} if meta.get('title') else {'title': request_title(prompt)}) | ({} if roots == saved else {'roots': roots})
            if fill: _set_session_meta(self, sid, **fill)

class HistoryBusy(RuntimeError):
    "The log cannot be compacted now: a writer holds it, or another live process holds a session."

def _live_sessions(cfg):
    "`{session: pid}` for each session another live process holds."
    held = {d.parent.name: _pid_in(d) for d in (Path(cfg)/'runs').glob(f'*/{LOCK}')}
    return {s: pid for s, pid in held.items() if pid and pid != os.getpid() and _alive(pid)}

def _lock_log(f, wait):
    "Take `f`'s exclusive lock, the one `_append_line` takes, waiting up to `wait` seconds for a writer to finish."
    import fcntl
    end = time.monotonic() + wait
    while True:
        try: return fcntl.flock(f, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            if time.monotonic() >= end: raise HistoryBusy(f'{f.name} is being written; try again in a moment') from None
            time.sleep(0.05)

def _details_ids(p):
    "The call ids a details file already holds whole."
    out = set()
    if p.exists():
        for d in map(_log_turn, p.read_bytes().split(b'\n')):
            if isinstance(d, dict) and isinstance(d.get('details'), dict): out |= set(d['details'])
    return out

def _compacted(row, ref, held):
    "`row` as `compact_history` keeps it, and the results to move to the details file `ref` (none without one): those `held` lacks."
    new = row
    if isinstance(row.get('prompt'), str) and (p := turn_prompt(row)) != row['prompt']: new = new | {'prompt': p}
    long = _long_details(new) if ref else {}
    if long: new = _clipped(new, long, ref)
    return new, {k: v for k, v in long.items() if k not in held}

def compact_history(
    cfg,                   # the config folder holding the log
    history_name='agent',  # names the conversation, as for `Agent`
    backup=True,           # keep the old log and index as `<name>.pre-compact`
    force=False,           # go on although another live process holds a session
    wait=10.,              # seconds to wait for a writer to finish before giving up
):
    "Rewrite the log once: a picture's bytes become `[image]` and results over `RESUME_DETAIL` move to the session's details file. Returns the sizes and counts."
    import fcntl
    cfg = Path(cfg).expanduser()
    log, index = cfg/f'{history_name}-history.jsonl', cfg/f'{history_name}-sessions.json'
    if not log.exists(): raise FileNotFoundError(f'no history at {log}')
    if not force and (live := _live_sessions(cfg)):
        raise HistoryBusy('quit the Ramabana processes holding sessions, or pass --force: ' + ', '.join(f'{s} (process {pid})' for s, pid in live.items()))
    kept = [p.with_name(p.name + '.pre-compact') for p in (log, index)]
    if backup and (old := [p for p in kept if p.exists()]): raise FileExistsError(f'{old[0]} exists; move it away or pass --no-backup')
    got = dict(rows=0, rewritten=0, images=0, results=0)
    with open(log, 'ab') as lock:
        _lock_log(lock, wait)
        try:
            if _replaced(lock, log): raise HistoryBusy(f'{log.name} was replaced while this waited; run it again')
            got['before'] = log.stat().st_size
            held = {}
            with tempfile.NamedTemporaryFile('wb', dir=cfg, prefix=log.name + '.', suffix='.compact', delete=False) as out:
                try:
                    with open(log, 'rb') as src:
                        for raw in src:
                            got['rows'] += 1
                            row = _log_turn(raw) if raw.endswith(b'\n') else None
                            new, moved, sid = row, {}, ''
                            if isinstance(row, dict):
                                sid = row.get('session') or ''
                                ref = f'{history_name}-details/{sid}.jsonl' if sid and Path(sid).name == sid else ''
                                if ref and sid not in held: held[sid] = _details_ids(cfg/ref)
                                new, moved = _compacted(row, ref, held.get(sid, ()))
                            if new is row: out.write(raw); continue
                            if moved:
                                d = cfg/ref
                                d.parent.mkdir(parents=True, exist_ok=True)
                                _append_line(d, json.dumps({'turn_id': row.get('turn_id', ''), 'details': moved}, ensure_ascii=False) + '\n')
                                held[sid] |= set(moved)
                            out.write(json.dumps(new, ensure_ascii=False).encode() + b'\n')
                            got['rewritten'] += 1; got['images'] += new.get('prompt') != row.get('prompt'); got['results'] += len(moved)
                    out.flush(); os.fsync(out.fileno())
                    if not got['rewritten']: Path(out.name).unlink(); return got | {'after': got['before'], 'index_rows': 0}
                    os.chmod(out.name, log.stat().st_mode & 0o777)
                    if backup:
                        os.link(log, kept[0])
                        if index.exists(): os.link(index, kept[1])
                    os.replace(out.name, log)
                except BaseException:
                    Path(out.name).unlink(missing_ok=True); raise
            got['after'] = log.stat().st_size
            a = Agent.__new__(Agent); a.cfg, a.history_name = cfg, history_name   # the index needs paths and locks, not a model
            got['index_rows'] = len(a.rebuild_index(force=True))
        finally: fcntl.flock(lock, fcntl.LOCK_UN)
    return got

